-- Khoá "Tiếng Nhật IT" — 15 bài theo giáo trình ITの日本語 B2 会話編 (thư mục nihongo_B2/).
-- Sinh từ nihongo_B2/第N課/03-tu-vung.md (từ vựng) và 02-hoi-thoai-mau-va-doc-hieu.md
-- (mẫu câu trọng tâm). Chỉ INSERT/UPSERT, KHÔNG xoá nội dung IT "original" cũ
-- (seed_content_it_original.sql) — cần gỡ nội dung cũ trước khi apply, nếu không bài sẽ hiện lẫn cả hai bản.
-- Câu ví dụ: nguyên văn (kèm bản dịch) từ hội thoại/bài tập của sách; từ không xuất hiện trong
-- câu nào của sách được bổ sung 1 câu do Claude soạn (cần user rà soát).
-- Từ vựng gồm cả bảng "Cụm từ" của từng bài, xếp sau danh sách từ.

begin;

values ('IT', 'Tiếng Nhật IT', 6)
on conflict (code) do update set title = excluded.title, order_index = excluded.order_index;

on conflict (id) do update set title = excluded.title, description = excluded.description, order_index = excluded.order_index;

on conflict (id) do nothing;

on conflict (vocabulary_id, order_index) do update set meaning_vi = excluded.meaning_vi, example_jp = excluded.example_jp, example_vi = excluded.example_vi, extra_examples_jp = excluded.extra_examples_jp, extra_examples_vi = excluded.extra_examples_vi;

on conflict (id) do nothing;

on conflict (lesson_id, item_type, item_id) do update set order_index = excluded.order_index;

commit;
