  ('07b4ddc1-6362-5982-a418-be77fc2ae187'::uuid, '誠に', 'まことに', 'Chào hỏi khi kết thúc onsite', (select id from jlpt_levels where code = 'IT'))
insert into vocabulary_meanings (vocabulary_id, order_index, meaning_vi, example_jp, example_vi, extra_examples_jp, extra_examples_vi)
values
  ('19d8e2f7-c4b5-5251-9ced-dac2438f6419'::uuid, 0, 'người phụ trách', '今回のプロジェクト責任者の小巻と申します。', 'Tôi là Komaki, người phụ trách dự án lần này.', array['SES社のプロジェクト責任者が2日間ベトナムに出張し、キックオフ会議を行います。', '私はE-Learningプロジェクト開発の責任者をつとめることになりました。カインと申します。'], array['Người phụ trách dự án của SES đi công tác tại Việt Nam hai ngày và tổ chức họp kickoff.', 'Tôi là Khánh, được giao làm người phụ trách phát triển dự án E-Learning.']),
  ('fc86fc15-cfbe-5239-bb81-a795c9e929b3'::uuid, 0, 'đi công tác', 'SES社のプロジェクト責任者が2日間ベトナムに出張し、キックオフ会議を行います。', 'Người phụ trách dự án của SES đi công tác tại Việt Nam hai ngày và tổ chức họp kickoff.', '{}'::text[], '{}'::text[]),
  ('c877d03c-de47-518e-9d49-8a2423df701d'::uuid, 0, 'họp khởi động dự án, kickoff meeting', 'SES社のプロジェクト責任者が2日間ベトナムに出張し、キックオフ会議を行います。', 'Người phụ trách dự án của SES đi công tác tại Việt Nam hai ngày và tổ chức họp kickoff.', '{}'::text[], '{}'::text[]),
  ('4bc799d0-c7bc-5326-98d7-ff1ae692c592'::uuid, 0, 'trao đổi danh thiếp', '本日は1日目で、名刺交換のあとに両社があいさつします。', 'Hôm nay là ngày đầu tiên; sau khi trao đổi danh thiếp, hai công ty chào hỏi nhau.', '{}'::text[], '{}'::text[]),
  ('ae5b9d40-2218-5f4f-acdd-2bad9fa06f39'::uuid, 0, 'vinh dự, vinh hạnh', '〜ができて、光栄です', 'Rất vinh dự vì có thể ~.', array['アンさんは何が光栄だと言っていましたか。', 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。'], array['Anh/chị An nói điều gì là vinh dự?', 'Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.']),
  ('b3841bf5-83f0-56db-bcab-3206a51e624d'::uuid, 0, 'dành cho, hướng tới', '日本企業向けシステム開発部門を管理しております、ホアンと申します。', 'Tôi là Hoan, phụ trách bộ phận phát triển hệ thống cho doanh nghiệp Nhật.', array['私は日本のお客様向けのシステム開発プロジェクトを主に担当しております。', '私は、日本のお客様向けのシステム開発プロジェクトを主に担当しております。'], array['Tôi chủ yếu phụ trách các dự án phát triển hệ thống cho khách hàng Nhật.', 'Tôi chủ yếu phụ trách các dự án phát triển hệ thống cho khách hàng Nhật.']),
  ('2beb1de1-95b2-565b-8189-ce497a9b2a5e'::uuid, 0, 'phát triển hệ thống', 'システム開発部長のホアンです。', 'Tôi là Hoan, trưởng bộ phận phát triển hệ thống.', array['システム開発部長をしております、ホアンと申します。', '私はシステム開発部門でSEをしています。リーと申します。'], array['Tôi là Hoan, trưởng bộ phận phát triển hệ thống.', 'Tôi là Lee, hiện đang làm SE ở bộ phận phát triển hệ thống.']),
  ('572e9aaf-252a-5582-ba48-8f565067caaf'::uuid, 0, 'bộ phận/phòng ban', '私はシステム開発部門でSEをしています。リーと申します。', 'Tôi là Lý, hiện đang làm SE ở bộ phận phát triển hệ thống.', array['日本企業向けシステム開発部門を管理しております、ホアンと申します。', '私は、弊社のIT部門でプロジェクトを管理しています。小巻と申します。'], array['Tôi là Hoan, phụ trách bộ phận phát triển hệ thống cho doanh nghiệp Nhật.', 'Tôi là Komaki, đang quản lý dự án tại bộ phận IT của công ty chúng tôi.']),
  ('ffeaf870-2345-57a2-bd78-cd17bad06b54'::uuid, 0, 'đảm nhận chức vụ/vai trò', '〜をつとめることになりました', 'Được quyết định/phân công đảm nhận vai trò ~.', array['今回のプロジェクトのPMをつとめることになりました、アンと申します。', '私はE-Learningプロジェクト開発の責任者をつとめることになりました。カインと申します。'], array['Tôi là An, được phân công làm PM của dự án lần này.', 'Tôi là Khánh, được giao làm người phụ trách phát triển dự án E-Learning.']),
  ('214e9e8f-0fdc-5a57-a32b-cf508f5d6063'::uuid, 0, 'thăm, ghé thăm', '今回は、ご多忙にもかかわらずご訪問くださり、まことにありがとうございます。', 'Cảm ơn quý vị đã ghé thăm dù rất bận rộn.', '{}'::text[], '{}'::text[]),
  ('b38aa990-eb5c-54bf-ab42-109e66dee60c'::uuid, 0, 'công ty chúng tôi (khiêm nhường ngữ)', '私は、弊社のIT部門でプロジェクトを管理しています。小巻と申します。', 'Tôi là Komaki, đang quản lý dự án tại bộ phận IT của công ty chúng tôi.', array['はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'これに関しては弊社でも承知しています。'], array['Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.', 'Về việc này, công ty chúng tôi cũng đã nắm rõ.']),
  ('04157572-62ea-5510-ba43-e4969c8ab1da'::uuid, 0, 'gặp trực tiếp, đối mặt', 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.', '{}'::text[], '{}'::text[]),
  ('2befa87d-78ca-51fd-aa25-3c047c1101e0'::uuid, 0, 'về nước', 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.', array['本日の定例会で話があった通り、帰国したらチーム全員で良かった点、改善すべき点について相談し、まとめます。'], array['Như đã nói trong cuộc họp định kỳ hôm nay, sau khi về nước tôi sẽ cùng toàn đội trao đổi và tổng hợp các điểm tốt, điểm cần cải thiện.']),
  ('91b30e32-7796-5535-8373-c33919b20ed8'::uuid, 0, 'xác định/định nghĩa yêu cầu', 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.', array['要件定義書で不明点が見つかったら、確認させてください。', 'SEのリーダーは要件定義からオンサイトし、UATとデプロイメントもサポートします。'], array['Nếu tìm thấy điểm chưa rõ trong tài liệu định nghĩa yêu cầu, xin cho tôi xác nhận lại.', 'Trưởng nhóm SE sẽ onsite từ giai đoạn định nghĩa yêu cầu, đồng thời hỗ trợ UAT và deployment.']),
  ('c9182292-02cc-5a10-b1fe-9e8f79bfda38'::uuid, 0, 'công đoạn, quy trình', 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.', array['設計工程の品質に関するデータを更新して報告してください。'], array['Hãy cập nhật dữ liệu về chất lượng của công đoạn thiết kế rồi báo cáo.']),
  ('546c17b4-1fe2-502e-8c77-e2d96a992f63'::uuid, 0, 'onsite; làm việc tại công ty khách hàng', 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.', array['本日はリーさんのオンサイト最終日です。', 'リーさんのオンサイト初日であいさつが終わりました。'], array['Hôm nay là ngày onsite cuối cùng của chị Lee.', 'Phần chào hỏi trong ngày onsite đầu tiên của chị Lee đã kết thúc.']),
  ('68c05d2e-3069-5d2a-b539-c01af0f1783f'::uuid, 0, 'phân tích', 'まず原因を分析し、対応する担当を切り分け、再現手順も確認します。', 'Trước hết, phân tích nguyên nhân, phân chia người phụ trách xử lý và xác nhận cả bước tái hiện.', array['分析に加えて、私が対応するものとオフショアが対応するものの切り分けもします。'], array['Ngoài phân tích, tôi cũng phân loại phần tôi xử lý và phần offshore xử lý.']),
  ('f9002771-c41f-5bdd-a909-971c436343a7'::uuid, 0, 'tham khảo', '過去のプロジェクトを参考にして、見積りを作成します。', 'Tôi lập báo giá dựa trên việc tham khảo các dự án trước đây.', '{}'::text[], '{}'::text[]),
  ('a537b631-3500-5528-aff1-8caa97307216'::uuid, 0, 'bộ phận, phòng ban', 'プログラミング言語がC#の場合は、この部署が担当するということですね。', 'Nếu ngôn ngữ lập trình là C#, nghĩa là bộ phận này phụ trách, đúng không ạ?', '{}'::text[], '{}'::text[]),
  ('aa43d34d-ff55-5773-9c22-94b65382cda7'::uuid, 0, 'nhận ủy thác', '弊社はシステムの受託開発を行っています。', 'Công ty chúng tôi thực hiện phát triển hệ thống theo hợp đồng ủy thác.', '{}'::text[], '{}'::text[]),
  ('c68659f9-e6aa-561c-bb32-f4ffdbf37238'::uuid, 0, 'phái cử nhân sự', 'SESからエンジニアを派遣してもらいます。', 'Chúng tôi sẽ được SES phái kỹ sư đến.', '{}'::text[], '{}'::text[]),
  ('9036e80a-94d6-5a53-bd0c-0a5baf3bcb03'::uuid, 0, 'các loại', '各種ドキュメントは共有フォルダに保存してあります。', 'Các loại tài liệu được lưu sẵn trong thư mục chia sẻ.', '{}'::text[], '{}'::text[]),
  ('fbd7c9fb-3e7a-5232-854a-5b0d6abbd245'::uuid, 0, 'quản lý nhân sự', '人事管理システムのユーザー管理機能の実装は64%完了しました。', 'Việc triển khai chức năng quản lý người dùng của hệ thống quản lý nhân sự đã hoàn thành 64%.', '{}'::text[], '{}'::text[]),
  ('f61147d0-0a70-5485-999c-c83bf6108472'::uuid, 0, 'họp khởi động dự án, kickoff meeting', 'では、プロジェクトのキックオフミーティングを始めたいと思います。', 'Vậy, tôi xin phép bắt đầu cuộc họp kickoff dự án.', array['キックオフミーティングで、引き続きPMが体制について紹介します。', 'E-Learningプロジェクトのキックオフミーティングを行います。'], array['Trong cuộc họp kickoff, PM tiếp tục giới thiệu về cơ cấu dự án.', 'Tổ chức cuộc họp kickoff của dự án E-Learning.']),
  ('97dc19a5-372a-5f06-91e2-ad44b2386ccf'::uuid, 0, 'tạm trú, lưu trú', '今回は3日間ベトナムに滞在する予定です。', 'Lần này dự kiến tôi lưu lại Việt Nam 3 ngày.', '{}'::text[], '{}'::text[]),
  ('8e1bc1c8-dbd0-50ee-ac4d-24dbfda8bb7a'::uuid, 0, 'bận rộn', '今回は、ご多忙にもかかわらずご訪問くださり、まことにありがとうございます。', 'Cảm ơn quý vị đã ghé thăm dù rất bận rộn.', '{}'::text[], '{}'::text[]),
  ('deb02fb8-6b62-5c1e-9edd-63c0bf029214'::uuid, 0, 'quản lý dự án', 'ホアンさんは今年から会計システムのプロジェクトを管理することになっております。', 'Anh Hoan sẽ được phân công quản lý dự án hệ thống kế toán từ năm nay.', '{}'::text[], '{}'::text[]),
  ('8694159d-47c3-508d-bc19-22b02a8cc0f9'::uuid, 0, 'chủ yếu phụ trách ~', '私はテストを主に担当しています。', 'Tôi chủ yếu phụ trách kiểm thử.', '{}'::text[], '{}'::text[]),
  ('73315ad5-1262-5f16-b67b-6a709117031f'::uuid, 0, 'phụ trách với tư cách người thay thế/kế nhiệm', 'リーが後任として担当することになっております。', 'Lee được sắp xếp phụ trách với tư cách người kế nhiệm.', '{}'::text[], '{}'::text[]),
  ('ba167f95-eb59-533e-a499-69190f5a9c01'::uuid, 0, 'công đoạn xác định yêu cầu', 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.', '{}'::text[], '{}'::text[]),
  ('954060de-f06c-5e0d-8b06-072f605f2832'::uuid, 0, 'quý vị đến công ty chúng tôi', 'この度は、ご来社くださり、まことにありがとうございます。', 'Cảm ơn quý vị đã đến công ty chúng tôi lần này.', '{}'::text[], '{}'::text[]),
  ('f2291f30-211f-5f46-abf6-baadd31e0d10'::uuid, 0, 'quý vị ghé thăm', '今回は、ご多忙にもかかわらずご訪問くださり、まことにありがとうございます。', 'Cảm ơn quý vị đã ghé thăm dù rất bận rộn.', '{}'::text[], '{}'::text[]),
