  ('b63a7c84-d23b-5b07-abca-bf3baec6dace'::uuid, 0, 'khái quát, tổng quan', 'まず、プロジェクト概要についてです。', 'Trước hết là tổng quan dự án.', array['PMのアンさんがプロジェクトの概要を紹介します。', 'では、プロジェクト概要について説明を始めたいと思います。'], array['An, PM, giới thiệu tổng quan dự án.', 'Vậy tôi xin bắt đầu giải thích về tổng quan dự án.']),
  ('c63ade5f-644a-5c6e-912b-ca8ffad41aa8'::uuid, 0, 'tài liệu', '（資料を画面に映す）', '(Chiếu tài liệu lên màn hình.)', array['キックオフ資料は何について書いてありますか。', '次に、弊社がキックオフ資料を説明いたします。'], array['Tài liệu kickoff viết về những nội dung gì?', 'Tiếp theo, công ty chúng tôi sẽ giải thích tài liệu kickoff.']),
  ('efce4193-a331-5f79-93c7-dad1964dad9d'::uuid, 0, 'chương trình cuộc họp, agenda', 'まず、本日のアジェンダについて説明いたします。', 'Trước hết, tôi xin giải thích agenda hôm nay.', array['このアジェンダでプロジェクトのキックオフミーティングを進めたいと思いますが、よろしいでしょうか。'], array['Chúng tôi xin tiến hành cuộc họp khởi động dự án theo chương trình họp này, được không ạ?']),
  ('36bd3471-dd42-55cc-9616-7db171fecdd6'::uuid, 0, 'trao đổi, thảo luận', 'そして、最後にQ&Aと相談をします。', 'Cuối cùng, chúng ta sẽ hỏi đáp và trao đổi.', array['両社で進め方について相談します。', '相談したいことがありますが、お時間よろしいですか。'], array['Hai công ty trao đổi về cách tiến hành.', 'Tôi có việc muốn trao đổi; anh/chị có thời gian không?']),
  ('cb28781e-9a82-5c30-92bc-55b3c756ed07'::uuid, 0, 'thứ tự', 'この順番で進めたいと思いますが、よろしいでしょうか。', 'Chúng ta tiến hành theo trình tự này được chứ?', '{}'::text[], '{}'::text[]),
  ('90febf21-2d7a-5614-80b8-ddcfd4f2f625'::uuid, 0, 'tiến hành', 'この順番で進めたいと思いますが、よろしいでしょうか。', 'Chúng ta tiến hành theo trình tự này được chứ?', array['このアジェンダでプロジェクトのキックオフミーティングを進めたいと思いますが、よろしいでしょうか。', '両社で進め方について相談します。'], array['Chúng tôi xin tiến hành cuộc họp khởi động dự án theo chương trình họp này, được không ạ?', 'Hai công ty trao đổi về cách tiến hành.']),
  ('a9e9b9cb-3115-5c38-8e1e-f29e165b5d34'::uuid, 0, 'kỹ thuật số', 'デジタル教科書アプリの受入テストと展開も無事終わりました。', 'Kiểm thử nghiệm thu và triển khai ứng dụng sách giáo khoa số cũng đã hoàn tất thuận lợi.', array['デジタル教科書のデスクトップアプリケーションを開発しました。', '昨年は、デジタル教科書のデスクトップアプリケーションを開発していただき、ありがとうございました。'], array['Đã phát triển ứng dụng desktop cho sách giáo khoa số.', 'Cảm ơn mọi người đã phát triển ứng dụng desktop cho sách giáo khoa số năm ngoái.']),
