  ('a900aa80-2d9d-536e-98de-1cfedf04d0b0'::uuid, 0, 'tổ chức, cơ cấu dự án', 'キックオフ資料の内容は、プロジェクトの概要、体制、開発手法、スケジュール、コミュニケーションプラン、リスクと課題です。', 'Nội dung tài liệu kickoff gồm tổng quan dự án, cơ cấu, phương pháp phát triển, lịch trình, kế hoạch giao tiếp, rủi ro và vấn đề.', array['こちらがプロジェクトの体制です。', 'ご質問がなければ、体制とメンバーについて紹介いたします。'], array['Đây là cơ cấu dự án.', 'Nếu không có câu hỏi, tôi xin giới thiệu cơ cấu và các thành viên.']),
  ('f03c7696-1d68-5d5d-b7bb-ec3b9b93cf43'::uuid, 0, 'phương thức phát triển', 'キックオフ資料の内容は、プロジェクトの概要、体制、開発手法、スケジュール、コミュニケーションプラン、リスクと課題です。', 'Nội dung tài liệu kickoff gồm tổng quan dự án, cơ cấu, phương pháp phát triển, lịch trình, kế hoạch giao tiếp, rủi ro và vấn đề.', array['このプロジェクトにとっては、アジャイルの方が適した開発手法だと思います。', '内容は体制、開発手法、コミュニケーションプランとリスク・課題の4つです。'], array['Tôi nghĩ Agile là phương pháp phát triển phù hợp hơn với dự án này.', 'Nội dung gồm bốn phần: cơ cấu, phương thức phát triển, kế hoạch giao tiếp và rủi ro/vấn đề.']),
  ('2f0189eb-0322-5227-95a6-d1cd38df852c'::uuid, 0, 'kế hoạch giao tiếp', 'まず、コミュニケーションプランについて説明いたします。', 'Trước hết, tôi xin giải thích về kế hoạch giao tiếp.', array['キックオフ資料の内容は、プロジェクトの概要、体制、開発手法、スケジュール、コミュニケーションプラン、リスクと課題です。', '内容は体制、開発手法、コミュニケーションプランとリスク・課題の4つです。'], array['Nội dung tài liệu kickoff gồm tổng quan dự án, cơ cấu, phương pháp phát triển, lịch trình, kế hoạch giao tiếp, rủi ro và vấn đề.', 'Nội dung gồm bốn phần: cơ cấu, phương thức phát triển, kế hoạch giao tiếp và rủi ro/vấn đề.']),
  ('376fda0e-4708-5df8-90af-7b265a4345ca'::uuid, 0, 'vấn đề, hạng mục cần xử lý', 'まず、現在のシステムの課題について説明いたします。', 'Trước hết, tôi xin giải thích về các vấn đề của hệ thống hiện tại.', array['キックオフ資料の内容は、プロジェクトの概要、体制、開発手法、スケジュール、コミュニケーションプラン、リスクと課題です。', '課題は全体の進捗に影響していますか。'], array['Nội dung tài liệu kickoff gồm tổng quan dự án, cơ cấu, phương pháp phát triển, lịch trình, kế hoạch giao tiếp, rủi ro và vấn đề.', 'Vấn đề có ảnh hưởng đến tiến độ chung không?']),
  ('9beb51d5-e818-5b2d-a4ed-429ca046a7ce'::uuid, 0, 'theo thứ tự, theo trình tự', 'では、順を追って説明いたします。', 'Tôi sẽ giải thích lần lượt.', '{}'::text[], '{}'::text[]),
