  ('739b5451-d99e-5351-a2ee-e6b1775d9ad6'::uuid, 0, 'so sánh', '二つのツールを比較して、どちらを使うか決めましょう。', 'Hãy so sánh hai công cụ rồi quyết định dùng cái nào.', '{}'::text[], '{}'::text[]),
  ('c3425378-5272-583f-b921-fb23cec2d50d'::uuid, 0, 'đối tượng', 'テスト対象外の場合は、皆さんが追記するということですね。', 'Nếu nằm ngoài đối tượng kiểm thử thì các bạn sẽ ghi bổ sung, đúng không ạ?', array['ご要望に応じて、今回の修正対象外の点についても追記しています。', '新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。'], array['Theo mong muốn của quý vị, chúng tôi cũng ghi bổ sung những điểm nằm ngoài phạm vi sửa lần này.', 'Tôi đã ghi thêm “Mới” cho màn hình mới và “Ngoài phạm vi Web hóa” cho phần không cần triển khai ở bản Web.']),
  ('7ee3fe48-0f93-55c5-be02-1ed6f0977bf1'::uuid, 0, 'kịch bản kiểm thử', 'テスト対象は8機能で、自動テストツールはテストスクリプトを自動で生成できます。', 'Có 8 chức năng cần kiểm thử, và công cụ kiểm thử tự động có thể tự động sinh kịch bản kiểm thử.', '{}'::text[], '{}'::text[]),
  ('92ed14f7-5a69-58be-aa23-6f443f583c3f'::uuid, 0, 'sinh ra, generate', 'このツールはレポートを自動で生成します。', 'Công cụ này tự động tạo (generate) báo cáo.', '{}'::text[], '{}'::text[]),
  ('9f6c1a7b-f065-54da-ae82-3f7e12c87d7b'::uuid, 0, 'trong tay, bên cạnh mình', '手元の資料をご覧ください。', 'Xin mời xem tài liệu trong tay quý vị.', '{}'::text[], '{}'::text[]),
  ('4593bc23-9e9f-580b-bbe7-f84fa5e797ea'::uuid, 0, 'thứ tự, trật tự', '作業の順序を確認しましょう。', 'Hãy xác nhận thứ tự công việc.', '{}'::text[], '{}'::text[]),
  ('cb32927f-2463-5322-93f4-6d7112d85bee'::uuid, 0, 'master schedule, kế hoạch tổng thể', '次に、マスタースケジュールと進め方について説明いたします。', 'Tiếp theo, tôi xin giải thích master schedule và cách tiến hành.', array['PMのアンさんがプロジェクトのマスタースケジュールと開発手法を紹介します。'], array['An, PM, giới thiệu master schedule và phương thức phát triển của dự án.']),
  ('20bbf7a0-97c4-5247-a565-3fe58b0ad9ae'::uuid, 0, 'cách tiến hành', '両社で進め方について相談します。', 'Hai công ty trao đổi về cách tiến hành.', array['次に、マスタースケジュールと進め方について説明いたします。'], array['Tiếp theo, tôi xin giải thích master schedule và cách tiến hành.']),
  ('2e12c00c-9aae-5d58-a9b8-fc3f6b315b1f'::uuid, 0, 'quá trình', 'UIは開発の過程で修正してもよいことになっていますか。', 'Có được sửa UI trong quá trình phát triển không?', '{}'::text[], '{}'::text[]),
  ('1124e4cc-d2d3-5a34-a956-8e379767f02d'::uuid, 0, 'sửa, chỉnh sửa', 'UIは開発の過程で修正してもよいことになっていますか。', 'Có được sửa UI trong quá trình phát triển không?', array['はい。「Web化_修正点」というものですか。', '変更する場合は、いくつか修正する必要が出てくると思います。'], array['Vâng, là file có tên “Web hóa_điểm sửa đổi”, đúng không ạ?', 'Nếu thay đổi thì tôi nghĩ sẽ phát sinh nhu cầu phải sửa một số điểm.']),
  ('a5108c5e-dba2-55fd-bc11-40726779d625'::uuid, 0, 'việc làm lại', 'そうすれば、手戻りを減らせると考えています。', 'Bằng cách đó, tôi cho rằng có thể giảm việc làm lại.', array['プロジェクトでは、手戻りを減らすためにどんなことをする予定ですか。'], array['Dự án dự định làm gì để giảm việc phải làm lại?']),
  ('f89f4c36-1ac9-5782-b0a2-5e754147f95e'::uuid, 0, 'giảm (việc làm lại)', 'レビューを早めに行って、手戻りを減らします。', 'Review sớm để giảm việc làm lại.', '{}'::text[], '{}'::text[]),
  ('8faccd2e-af21-585f-9a66-f3b97978e0a4'::uuid, 0, 'input, tư liệu đầu vào', 'SRS、UIなどインプットは御社より提供していただき、弊社がコーディング、UT、ITをベトナムで行います。', 'Các input như SRS, UI do quý công ty cung cấp; công ty chúng tôi thực hiện coding, UT và IT tại Việt Nam.', '{}'::text[], '{}'::text[]),
  ('3c7ae9d2-f9fd-57d7-a166-433390f85e1c'::uuid, 0, 'quý công ty, công ty các bạn', 'UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。', 'Để kiểm tra UI có đúng như kỳ vọng của quý công ty không, chúng tôi đề xuất thực hiện ba buổi demo.', array['SRS、UIなどインプットは御社より提供していただき、弊社がコーディング、UT、ITをベトナムで行います。', '詳しいことが決まったら、また御社に連絡しますね。'], array['Các input như SRS, UI do quý công ty cung cấp; công ty chúng tôi thực hiện coding, UT và IT tại Việt Nam.', 'Khi chi tiết được quyết định, chúng tôi sẽ liên lạc lại với quý công ty.']),
  ('7345709b-5919-54aa-808d-f5c990af4f2e'::uuid, 0, 'cung cấp', 'SRS、UIなどインプットは御社より提供していただき、弊社がコーディング、UT、ITをベトナムで行います。', 'Các input như SRS, UI do quý công ty cung cấp; công ty chúng tôi thực hiện coding, UT và IT tại Việt Nam.', '{}'::text[], '{}'::text[]),
  ('6decde45-fef6-5629-a8ba-8ed1196dde17'::uuid, 0, 'deployment, triển khai', 'SEのリーダーは要件定義からオンサイトし、UATとデプロイメントもサポートします。', 'Trưởng nhóm SE sẽ onsite từ giai đoạn định nghĩa yêu cầu, đồng thời hỗ trợ UAT và deployment.', '{}'::text[], '{}'::text[]),
  ('e13f64a0-2fae-57fc-ae64-583f9d17b632'::uuid, 0, 'chỉ, báo, hướng dẫn, dạy', 'ロジックに合わせて直したほうがよいものがありましたら、教えていただければと思います。', 'Nếu có điểm nào nên sửa cho phù hợp với logic, mong quý vị cho biết.', array['SESの勤務時間について教えてください。', 'それについて詳しく教えていただけますか。'], array['Hãy cho biết giờ làm việc tại SES.', 'Anh/chị có thể cho biết chi tiết về việc đó được không?']),
  ('a1c501e1-3a45-5c64-8900-230df8940f2f'::uuid, 0, 'mô hình waterfall/thác nước', '開発手法に関しては要件がかなりはっきりしているので、ウォーターフォールで開発を進めます。', 'Về phương thức phát triển, vì yêu cầu khá rõ nên chúng tôi sẽ phát triển theo mô hình waterfall.', '{}'::text[], '{}'::text[]),
  ('1abec843-81d6-510b-9fc1-1d2a291ac3c9'::uuid, 0, 'phát sinh', '変更が発生するかもしれませんが、ほぼ決まっていますので、それで問題ないと思います。', 'Có thể sẽ phát sinh thay đổi, nhưng phần lớn đã xác định, nên tôi nghĩ như vậy không có vấn đề gì.', array['メモリ不足が原因で、どのような状況が発生していますか。', 'プロジェクトで課題が発生した場合は、誰と誰が確認しますか。'], array['Thiếu bộ nhớ gây ra tình huống nào?', 'Khi phát sinh vấn đề trong dự án, ai sẽ xác nhận với ai?']),
  ('ac795562-b378-5f2b-b6db-6fdb73d65c3a'::uuid, 0, 'mong muốn, kỳ vọng', 'UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。', 'Để kiểm tra UI có đúng như kỳ vọng của quý công ty không, chúng tôi đề xuất thực hiện ba buổi demo.', '{}'::text[], '{}'::text[]),
  ('e3e853a7-2a54-506e-829b-b97174cd089c'::uuid, 0, 'demo', 'UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。', 'Để kiểm tra UI có đúng như kỳ vọng của quý công ty không, chúng tôi đề xuất thực hiện ba buổi demo.', array['そうですね。賛成です。実は、SRSで一部決まっていない内容があります。デモで何を改善すればよいか、はっきり見えるようになり、より良い製品ができると思いますので、ぜひ行いましょう。', 'では、学習結果確認機能の詳細画面のデモを始めます。'], array['Đúng vậy, tôi tán thành. Thực ra trong SRS có một số nội dung chưa được quyết định. Qua demo, sẽ thấy rõ cần cải thiện điều gì và có thể tạo ra sản phẩm tốt hơn, nên nhất định hãy thực hiện.', 'Vậy tôi xin bắt đầu demo màn hình chi tiết của chức năng xác nhận kết quả học tập.']),
  ('38f8e285-783a-5393-b336-ed262dda1cf9'::uuid, 0, 'đề xuất', 'UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。', 'Để kiểm tra UI có đúng như kỳ vọng của quý công ty không, chúng tôi đề xuất thực hiện ba buổi demo.', array['提案書に記載した通り、6月末に製品のデモを行います。', 'チームは次回のリリースで制限なしのバージョンを納品することを提案しましたが、お客様は合意しましたか。'], array['Như đã ghi trong đề xuất, chúng ta sẽ demo sản phẩm vào cuối tháng 6.', 'Nhóm đã đề xuất giao bản không giới hạn ở lần release sau, vậy khách hàng có đồng ý không?']),
  ('6ea27937-eaed-5339-8343-a1b47320f6da'::uuid, 0, 'khi đó, vì thế, do đó', 'そこで、端末のRAMは４GB以上を推奨しています。', 'Vì vậy, chúng tôi khuyến nghị RAM của thiết bị từ 4GB trở lên.', array['そこで、不具合が出た場合の体制について、念のためもう一度聞かせてください。', '来週は振り返り会議をすることになっていますが、そこでも良かった点として報告させてもらいます。'], array['Vì vậy, cho tôi hỏi lại để chắc chắn về cơ chế khi có lỗi.', 'Tuần sau sẽ có họp tổng kết; chúng tôi cũng sẽ báo cáo đây là một điểm tích cực.']),
  ('17a59ceb-fc61-5355-be7d-87966aacfaaf'::uuid, 0, 'đồng ý, tán thành', 'そうですね。賛成です。実は、SRSで一部決まっていない内容があります。デモで何を改善すればよいか、はっきり見えるようになり、より良い製品ができると思いますので、ぜひ行いましょう。', 'Đúng vậy, tôi tán thành. Thực ra trong SRS có một số nội dung chưa được quyết định. Qua demo, sẽ thấy rõ cần cải thiện điều gì và có thể tạo ra sản phẩm tốt hơn, nên nhất định hãy thực hiện.', '{}'::text[], '{}'::text[]),
  ('5d1dc9f9-b60a-50c8-bcea-d3e8f2435c1c'::uuid, 0, 'một phần, một số phần', '実は、SRSで一部決まっていない内容があります。', 'Thực ra, có một phần nội dung trong SRS chưa được quyết định.', array['メモリ不足が原因で、一部の画面が…動作しないのですね。', 'キックオフミーティングで説明した通り、一部機能の追加・修正を行います。'], array['Do thiếu bộ nhớ nên một số màn hình không hoạt động…, đúng không?', 'Như đã giải thích trong kickoff, chúng ta sẽ thêm/sửa một số chức năng.']),
  ('9e6fadd8-7177-59e9-892d-a637f987283b'::uuid, 0, 'cải thiện', 'そうですね。賛成です。実は、SRSで一部決まっていない内容があります。デモで何を改善すればよいか、はっきり見えるようになり、より良い製品ができると思いますので、ぜひ行いましょう。', 'Đúng vậy, tôi tán thành. Thực ra trong SRS có một số nội dung chưa được quyết định. Qua demo, sẽ thấy rõ cần cải thiện điều gì và có thể tạo ra sản phẩm tốt hơn, nên nhất định hãy thực hiện.', array['良かった点と改善すべき点について相談し、まとめます。', '本日の定例会で話があった通り、帰国したらチーム全員で良かった点、改善すべき点について相談し、まとめます。'], array['Họ sẽ trao đổi và tổng hợp các điểm tốt cùng những điểm cần cải thiện.', 'Như đã nói trong cuộc họp định kỳ hôm nay, sau khi về nước tôi sẽ cùng toàn đội trao đổi và tổng hợp các điểm tốt, điểm cần cải thiện.']),
  ('a6a13e8b-288b-57e2-8fe1-be28a5fbc200'::uuid, 0, 'phòng, ngăn ngừa', '事前にチェックして、ミスを防ぎます。', 'Kiểm tra trước để ngăn ngừa sai sót.', '{}'::text[], '{}'::text[]),
  ('a2dd29cd-2f1e-5456-82b7-1e677b65a4fc'::uuid, 0, 'đặc tả yêu cầu', '要件仕様書は完成したので、月曜日に送ります。', 'Tài liệu đặc tả yêu cầu đã hoàn thành nên tôi sẽ gửi vào thứ Hai.', '{}'::text[], '{}'::text[]),
  ('1ffad611-aa56-5179-9861-20784990a410'::uuid, 0, 'tài liệu thiết kế/design', '画面設計書は、２年前に開発されたシステムのものである。', 'Tài liệu thiết kế màn hình thuộc hệ thống phát triển hai năm trước.', array['画面を共有しましたので、設計書レビューを始めたいと思います。', 'モバイル版開発で追加・変更する部分には、画面設計書に「追加」または「変更」と記載した。'], array['Đã chia sẻ màn hình nên tôi muốn bắt đầu review tài liệu thiết kế.', 'Phần thêm/sửa ở bản mobile được ghi “Thêm” hoặc “Thay đổi” trong tài liệu thiết kế màn hình.']),
  ('5f2479fb-bd52-5dc2-8b45-8490b5761070'::uuid, 0, 'integration test, kiểm thử tích hợp', '結合テスト仕様書の作成は30%完了しました。', 'Việc lập tài liệu đặc tả kiểm thử tích hợp đã hoàn thành 30%.', array['現在は、実装と結合テスト仕様書作成を進めています。', '現在は、画面の実装 と 結合テスト仕様書作成 を進めています。'], array['Hiện tại, chúng tôi đang triển khai và lập tài liệu đặc tả kiểm thử tích hợp.', 'Hiện đang triển khai màn hình và lập tài liệu đặc tả kiểm thử tích hợp.']),
  ('65272770-29b5-5937-b952-cacd19dd85d3'::uuid, 0, 'triển khai', 'デジタル教科書アプリの受入テストと展開も無事終わりました。', 'Kiểm thử nghiệm thu và triển khai ứng dụng sách giáo khoa số cũng đã hoàn tất thuận lợi.', array['受入テストサポートと展開も終わり、本日はオンサイトの最終日です。'], array['Hỗ trợ UAT và triển khai đã kết thúc; hôm nay là ngày onsite cuối cùng.']),
  ('874e586b-2c51-54a7-b35f-cc332f272431'::uuid, 0, 'tạo, lập', '現在は、実装と結合テスト仕様書作成を進めています。', 'Hiện tại, chúng tôi đang triển khai và lập tài liệu đặc tả kiểm thử tích hợp.', array['現在は、画面の実装 と 結合テスト仕様書作成 を進めています。'], array['Hiện đang triển khai màn hình và lập tài liệu đặc tả kiểm thử tích hợp.']),
  ('55525eac-37ea-5d65-b422-b3ccaa7ded89'::uuid, 0, 'hằng ngày', '進捗は日次で報告します。', 'Tiến độ được báo cáo hằng ngày.', '{}'::text[], '{}'::text[]),
  ('427e6684-b343-5efa-b748-10bf87e1e25e'::uuid, 0, 'rõ ràng', '目的を明確にしてから、作業を始めましょう。', 'Hãy làm rõ mục đích rồi mới bắt đầu công việc.', '{}'::text[], '{}'::text[]),
  ('83680a13-4cc4-5818-825f-cf9215f8c77e'::uuid, 0, 'loại/xóa bỏ (việc làm lại)', '仕様を確認して、手戻りをなくしたいです。', 'Tôi muốn xác nhận đặc tả để loại bỏ việc làm lại.', '{}'::text[], '{}'::text[]),
  ('2e16dab0-b138-52e0-bd37-6344e19a2ed8'::uuid, 0, 'hằng tuần', '時間になりましたので、週次会議を始めたいと思います。', 'Đã đến giờ nên tôi muốn bắt đầu cuộc họp hằng tuần.', '{}'::text[], '{}'::text[]),
  ('ea69232b-aed9-5e38-97d7-2a5f15d9a410'::uuid, 0, 'tiến độ', '課題は全体の進捗に影響していますか。', 'Vấn đề có ảnh hưởng đến tiến độ chung không?', array['内容は進捗報告、リスク・課題と Q&A の3つです。', '昨日の夕方に、進捗の詳細をまとめた WBS と進捗報告書 を送付しました。'], array['Nội dung gồm ba phần: báo cáo tiến độ, rủi ro/vấn đề và Q&A.', 'Chiều hôm qua đã gửi WBS tổng hợp chi tiết tiến độ và báo cáo tiến độ.']),
  ('b0e0c45c-41d9-54e5-b70e-578c70798575'::uuid, 0, 'tiếp tục', 'キックオフミーティングで、引き続きPMが体制について紹介します。', 'Trong cuộc họp kickoff, PM tiếp tục giới thiệu về cơ cấu dự án.', array['営業と契約に関しては当初から御社とやりとりをさせていただいているリンが引き続き担当します。', '引き続きよろしくお願いいたします。'], array['Về kinh doanh và hợp đồng, Lin — người đã trao đổi với quý công ty từ đầu — tiếp tục phụ trách.', 'Mong tiếp tục được hợp tác.']),
  ('04ec4495-d97c-5774-bf34-03956727de5c'::uuid, 0, 'report line', 'レポートラインについては弊社も同じ認識です。', 'Về report line, phía chúng tôi cũng có cùng nhận thức.', array['プロジェクトのレポートラインについて教えてください。'], array['Hãy cho biết report line của dự án.']),
  ('a073a567-2b1f-5d21-ae6e-872d79bb652d'::uuid, 0, 'tổng phụ trách/quản lý tổng hợp dự án', '黒田様がプロジェクト統括管理者で、小巻様が御社のPMです。', 'Ngài Kuroda là quản lý tổng hợp dự án và chị Komaki là PM phía quý công ty.', '{}'::text[], '{}'::text[]),
  ('90ca58f8-1c8e-5dad-a469-ef6ff900b05d'::uuid, 0, 'kinh doanh, bán hàng', '営業と契約に関しては当初から御社とやりとりをさせていただいているリンが引き続き担当します。', 'Về kinh doanh và hợp đồng, Lin — người đã trao đổi với quý công ty từ đầu — tiếp tục phụ trách.', '{}'::text[], '{}'::text[]),
  ('ea47a171-43d1-5f9f-bfe0-c1f81148b673'::uuid, 0, 'đảm bảo chất lượng', 'PMは私アンで、開発、テスト、コミュニケーション、品質保証の4つのチームを管理します。', 'PM là tôi, An, quản lý bốn nhóm: phát triển, kiểm thử, giao tiếp và đảm bảo chất lượng.', '{}'::text[], '{}'::text[]),
  ('9bca2705-b8e7-5205-84bb-002a883de7a1'::uuid, 0, 'ý hiểu, nhận thức, cách hiểu', 'レポートラインについては弊社も同じ認識です。', 'Về report line, phía chúng tôi cũng có cùng nhận thức.', array['この点に関しては、弊社でも認識しております。'], array['Về điểm này, công ty chúng tôi cũng đã nhận thức rõ.']),
  ('6bc7d291-468e-5b75-976e-d25c8de197eb'::uuid, 0, 'thường xuyên', '仕様がひんぱんに変わると、スケジュールに影響します。', 'Nếu đặc tả thay đổi thường xuyên sẽ ảnh hưởng đến lịch trình.', '{}'::text[], '{}'::text[]),
  ('ff2005a8-cc44-55c4-b07c-b41d6b8f5343'::uuid, 0, 'trao đổi qua lại', '営業と契約に関しては当初から御社とやりとりをさせていただいているリンが引き続き担当します。', 'Về kinh doanh và hợp đồng, Lin — người đã trao đổi với quý công ty từ đầu — tiếp tục phụ trách.', array['お客様に設計書を送るときは、社内でやりとりした内容をそのままにしないようにしてください。'], array['Khi gửi tài liệu thiết kế cho khách hàng, đừng để nguyên nội dung đã trao đổi nội bộ.']),
  ('8e547107-fc2a-5c1b-9ced-600f14baeaef'::uuid, 0, 'ngại, e dè', '困ったことがあったら、私や山本に遠慮なく相談してください。', 'Nếu có việc khó khăn, xin cứ trao đổi với tôi hoặc Yamamoto, đừng ngại.', array['今後、実装中に何かありましたら、遠慮なくいつでも聞いてください。'], array['Sau này nếu trong lúc triển khai có gì, cứ thoải mái hỏi bất cứ lúc nào.']),
  ('d57e6ba8-744b-5216-9cc9-f3ef04ec63fe'::uuid, 0, 'tổng hợp', '私がそれらの情報をまとめて、小巻様に報告します。', 'Tôi sẽ tổng hợp các thông tin đó và báo cáo cho chị Komaki.', array['良かった点と改善すべき点について相談し、まとめます。', '資料をレビューしている間に、修正すべき点をまとめてあります。'], array['Họ sẽ trao đổi và tổng hợp các điểm tốt cùng những điểm cần cải thiện.', 'Trong lúc review tài liệu, tôi đã tổng hợp sẵn những điểm cần sửa.']),
  ('9b1e19e8-2532-5cb6-9a29-ae6b3b520451'::uuid, 0, 'hợp đồng', '営業と契約に関しては当初から御社とやりとりをさせていただいているリンが引き続き担当します。', 'Về kinh doanh và hợp đồng, Lin — người đã trao đổi với quý công ty từ đầu — tiếp tục phụ trách.', '{}'::text[], '{}'::text[]),
  ('4c988865-01e6-5f94-bf07-c4503db62d90'::uuid, 0, 'ban đầu', '営業と契約に関しては当初から御社とやりとりをさせていただいているリンが引き続き担当します。', 'Về kinh doanh và hợp đồng, Lin — người đã trao đổi với quý công ty từ đầu — tiếp tục phụ trách.', '{}'::text[], '{}'::text[]),
  ('1282dd83-3686-5cdb-bfba-25fd98053a6b'::uuid, 0, 'giải quyết', 'プロジェクトで解決の難しい課題があれば、黒田様、ホアンにエスカレーションします。', 'Nếu có vấn đề khó giải quyết trong dự án, chúng tôi sẽ escalation tới ngài Kuroda và Hoan.', array['調査した結果、…すれば、解決することがわかりました。'], array['Sau khi điều tra, chúng tôi biết rằng nếu … thì có thể giải quyết.']),
  ('2a9f295a-fd0b-5db3-ae3d-d2236ab97586'::uuid, 0, 'escalate, báo cáo lên cấp trên', 'プロジェクトで解決の難しい課題があれば、黒田様、ホアンにエスカレーションします。', 'Nếu có vấn đề khó giải quyết trong dự án, chúng tôi sẽ escalation tới ngài Kuroda và Hoan.', '{}'::text[], '{}'::text[]),
  ('4c56696d-c134-5083-945e-c3696d814afb'::uuid, 0, 'cuộc họp định kỳ', 'その結果を次の定例会のときに報告してもよろしいですか。', 'Chúng tôi báo cáo kết quả trong cuộc họp định kỳ tới có được không ạ?', array['次回の定例会のアジェンダはこれでよいかご確認お願いします。', '本日の定例会で話があった通り、帰国したらチーム全員で良かった点、改善すべき点について相談し、まとめます。'], array['Xin hãy xác nhận agenda của cuộc họp định kỳ lần tới như thế này đã được chưa.', 'Như đã nói trong cuộc họp định kỳ hôm nay, sau khi về nước tôi sẽ cùng toàn đội trao đổi và tổng hợp các điểm tốt, điểm cần cải thiện.']),
  ('e3bc3d4c-ab57-532b-8101-8630bfa128b6'::uuid, 0, 'tổ chức', '毎週月曜日に定例会議を開催します。', 'Chúng tôi tổ chức họp định kỳ vào thứ Hai hằng tuần.', '{}'::text[], '{}'::text[]),
  ('eb2d28e1-6570-5d1d-a7e5-9e0ee391c245'::uuid, 0, 'chi tiết', 'では、学習結果確認機能の詳細画面のデモを始めます。', 'Vậy tôi xin bắt đầu demo màn hình chi tiết của chức năng xác nhận kết quả học tập.', array['詳細画面では、要件通り、画像を上部に配置しています。', '回答の詳細は、先週の木曜日に送付した資料をご確認ください。'], array['Ở màn hình chi tiết, theo đúng yêu cầu, chúng tôi đặt ảnh ở phía trên.', 'Xin hãy xem tài liệu tôi đã gửi vào thứ Năm tuần trước để biết chi tiết câu trả lời.']),
  ('9f111081-e937-5a70-a82e-b3eb9179038a'::uuid, 0, 'thiết lập, cài đặt', 'セキュリティソフトと開発環境を設定する。', 'Cài phần mềm bảo mật và môi trường phát triển.', array['では、席に戻ってパソコンの設定をしましょうか。', 'その後、リーさんは席に戻ってパソコンの設定をします。'], array['Vậy quay lại chỗ ngồi để cài máy tính nhé.', 'Sau đó Lee trở về chỗ ngồi để cài đặt máy tính.']),
