  ('b067247c-63b3-5bbd-b055-d27d198fb000'::uuid, 0, 'làm phiền', '皆さんに迷惑をかけないように気をつけます。', 'Tôi sẽ chú ý để không làm phiền mọi người.', '{}'::text[], '{}'::text[]),
  ('d4dee855-6152-5f54-b3fb-452a6c18f528'::uuid, 0, 'gỡ cài đặt', 'ご要望に応じて、アンインストールの手順についても記載しています。', 'Theo mong muốn của quý vị, chúng tôi cũng mô tả quy trình gỡ cài đặt.', array['ご要望に応じて、アンインストールの手順についても記載しています。', 'ご要望に応じて、インストール手順書には、アンインストールの手順についても記載しています。'], array['Theo mong muốn của các bạn, chúng tôi đang mô tả cả các bước gỡ cài đặt.', 'Theo yêu cầu của quý công ty, trong hướng dẫn cài đặt chúng tôi cũng ghi cả quy trình gỡ cài đặt.']),
  ('11795cd1-e3fe-5e15-81aa-a6e686710291'::uuid, 0, 'từng phần, nhỏ giọt/không đồng loạt', '資料は五月雨式で送りますので、届いたものから確認してください。', 'Tài liệu sẽ được gửi rải rác từng phần, nên hãy kiểm tra từ phần nào đến trước.', '{}'::text[], '{}'::text[]),
