  ('b1452832-6e3d-5958-9008-bbcd8ad30994'::uuid, 0, 'nghe/khai thác yêu cầu', 'お客様に要件をヒアリングします。', 'Tôi khai thác yêu cầu từ khách hàng.', '{}'::text[], '{}'::text[]),
  ('21483b9f-a9a1-5f34-9fa4-4607b5f7996c'::uuid, 0, 'phân tích nghiệp vụ', '要件ヒアリングのためにベトナムから来てくださった、さくらソフト社で業務分析をしているフォンさんです。', 'Đây là Phong, người làm phân tích nghiệp vụ tại công ty Sakura Soft, đã từ Việt Nam sang để nghe yêu cầu.', '{}'::text[], '{}'::text[]),
