  ('5928ecd1-69a7-519a-b016-e78c71d80aea'::uuid, 0, 'bảo mật, an ninh', 'セキュリティソフトと開発環境を設定する。', 'Cài phần mềm bảo mật và môi trường phát triển.', array['IT部門のセキュリティチェックを受けてから使用します。', '後で本日のセキュリティトレーニングの資料を送っておきますね。'], array['Phải được bộ phận IT kiểm tra bảo mật trước rồi mới được dùng trong công ty.', 'Lát nữa tôi sẽ gửi sẵn tài liệu đào tạo bảo mật hôm nay.']),
