  ('101c5b3e-8fb6-5ece-a4a0-8507da842f09'::uuid, 0, 'tủ có khóa', '退社するときは、資料を鍵付きロッカーにしまう。', 'Khi về cất tài liệu vào tủ khóa.', array['ノートパソコンを鍵付きロッカーに入れて帰ります。'], array['Cất laptop vào tủ khóa rồi về.']),
