  ('8f1e3c92-d347-52a8-933f-4805bc2820d0'::uuid, 0, 'nhận/qua kiểm tra bảo mật', 'IT部門のセキュリティチェックを受けてから使用します。', 'Phải được bộ phận IT kiểm tra bảo mật trước rồi mới được dùng trong công ty.', array['IT部門のセキュリティチェックを受けてからでないと、社内で使ってはいけないことになっています。'], array['Nếu chưa được bộ phận IT kiểm tra bảo mật thì không được dùng trong công ty.']),
  ('7c8d97c9-9264-5396-b71a-7423cc0a6647'::uuid, 0, 'cài phần mềm chống virus', 'パソコンにウイルス対策ソフトをインストールします。', 'Tôi cài phần mềm chống virus lên máy tính.', '{}'::text[], '{}'::text[]),
  ('d8e3cb05-c1c4-5a99-925f-01dbcde1468e'::uuid, 0, 'công cụ chống gửi nhầm email', '弊社で指定されているウイルス対策ソフトやメール誤送信防止ツールをインストールしましょう。', 'Chúng ta sẽ cài phần mềm chống virus và công cụ ngăn gửi nhầm email do công ty chỉ định.', '{}'::text[], '{}'::text[]),
  ('76ec20f6-b5e2-5a81-9bb1-ec7ae1003725'::uuid, 0, 'xin/đăng ký trước', '持ち出すときは、事前に申請します。', 'Khi mang ra ngoài, tôi đăng ký trước.', '{}'::text[], '{}'::text[]),
  ('8bc27d46-c187-553e-a939-24f422b14411'::uuid, 0, 'mang ra ngoài công ty', '社外へ持ち出すときは、許可が必要です。', 'Khi mang ra ngoài công ty cần có sự cho phép.', '{}'::text[], '{}'::text[]),
  ('6a50ada5-4ef7-5b54-9892-cd4d55950162'::uuid, 0, 'tập hợp; có mặt đầy đủ', 'プロジェクトのメンバーが全員そろいましたので、要件の説明会を始めたいと思います。', 'Vì toàn bộ thành viên dự án đã có mặt, tôi muốn bắt đầu buổi giải thích yêu cầu.', array['そろそろ終了時間ですので、残りの質問を含めて、今週中に回答していただけると幸いです。'], array['Sắp hết giờ, vì vậy chúng tôi rất mong nhận được câu trả lời cho cả các câu hỏi còn lại trong tuần này.']),
  ('c9179547-b195-5210-81a6-67638c10ce25'::uuid, 0, 'ngay tại chỗ, lúc đó', '説明の中で、わかりにくいところや確認しておきたいことがありましたら、その場で質問してください。', 'Nếu trong lúc giải thích có chỗ khó hiểu hoặc điều cần xác nhận, hãy hỏi ngay tại chỗ.', '{}'::text[], '{}'::text[]),
  ('19418833-a40e-512e-b0fa-4633bc0b5dad'::uuid, 0, 'chuyển thành bản Web, Web hóa', 'はい。「Web化_修正点」というものですか。', 'Vâng, là file có tên “Web hóa_điểm sửa đổi”, đúng không ạ?', array['このアプリをベースに、WebGLを使用してアプリをWeb化し、一部機能の追加・修正を行います。', '新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。'], array['Dựa trên ứng dụng này, dùng WebGL để Web hóa ứng dụng và thêm/sửa một số chức năng.', 'Tôi đã ghi thêm “Mới” cho màn hình mới và “Ngoài phạm vi Web hóa” cho phần không cần triển khai ở bản Web.']),
  ('0668938e-ad4a-52a4-8121-80784091285e'::uuid, 0, 'quen thuộc', 'この用語は、私たちにもなじみがあります。', 'Thuật ngữ này chúng tôi cũng quen thuộc.', '{}'::text[], '{}'::text[]),
  ('696a6ce1-0e54-5c7d-a746-111685091808'::uuid, 0, 'mới', '新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。', 'Tôi đã ghi thêm “Mới” cho màn hình mới và “Ngoài phạm vi Web hóa” cho phần không cần triển khai ở bản Web.', array['「新規」または「Web化対象外」の追記がない場合は、以前のアプリと同じ画面にするということですね。'], array['Nghĩa là nếu không có ghi thêm “Mới” hoặc “Ngoài phạm vi Web hóa”, thì sẽ dùng màn hình giống ứng dụng trước đây, đúng không ạ?']),
  ('35a3c123-6998-5315-bae7-700efe042230'::uuid, 0, 'ngoài đối tượng/phạm vi', 'テスト対象外の場合は、皆さんが追記するということですね。', 'Nếu nằm ngoài đối tượng kiểm thử thì các bạn sẽ ghi bổ sung, đúng không ạ?', array['新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。', '「新規」または「Web化対象外」の追記がない場合は、以前のアプリと同じ画面にするということですね。'], array['Tôi đã ghi thêm “Mới” cho màn hình mới và “Ngoài phạm vi Web hóa” cho phần không cần triển khai ở bản Web.', 'Nghĩa là nếu không có ghi thêm “Mới” hoặc “Ngoài phạm vi Web hóa”, thì sẽ dùng màn hình giống ứng dụng trước đây, đúng không ạ?']),
  ('9fedb66b-ca00-53ee-8aa9-2f328b556f6a'::uuid, 0, 'ghi chú/bổ sung thêm', 'テスト対象外の場合は、皆さんが追記するということですね。', 'Nếu nằm ngoài đối tượng kiểm thử thì các bạn sẽ ghi bổ sung, đúng không ạ?', array['追記がない場合は、以前のアプリと同じ画面にするということですね。', '新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。'], array['Nếu không có ghi thêm, nghĩa là dùng màn hình giống ứng dụng trước đây, đúng không ạ?', 'Tôi đã ghi thêm “Mới” cho màn hình mới và “Ngoài phạm vi Web hóa” cho phần không cần triển khai ở bản Web.']),
  ('13cccc60-c13f-57db-a58e-fe914b8949cb'::uuid, 0, 'lược bớt, rút gọn', '長いので、途中の説明は中略します。', 'Vì dài nên tôi lược bớt phần giải thích ở giữa.', '{}'::text[], '{}'::text[]),
  ('61a438a3-ab9c-510f-a126-916f0f11ef69'::uuid, 0, 'khác, riêng', 'これは別の問題として扱います。', 'Vấn đề này được xử lý như một vấn đề riêng.', '{}'::text[], '{}'::text[]),
  ('9b06ce88-d93b-5514-8e6c-95a830624c75'::uuid, 0, 'điểm nghi vấn, điều băn khoăn', '疑問点がでてきたら、確認させてください。', 'Nếu có điểm nghi vấn, xin cho chúng tôi xác nhận lại.', array['「モバイル化_特別対応」のファイルについて、いくつか疑問点をまとめているので、会議の場で確認したい。'], array['Team đã tổng hợp một số điểm nghi vấn về file đó và muốn xác nhận ngay trong cuộc họp.']),
  ('917af9b2-28de-52ac-a605-70232f72dff6'::uuid, 0, 'lập trình, triển khai (implement)', '今後、実装中に何かありましたら、遠慮なくいつでも聞いてください。', 'Sau này nếu trong lúc triển khai có gì, cứ thoải mái hỏi bất cứ lúc nào.', array['新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。', '現在は、実装と結合テスト仕様書作成を進めています。'], array['Tôi đã ghi thêm “Mới” cho màn hình mới và “Ngoài phạm vi Web hóa” cho phần không cần triển khai ở bản Web.', 'Hiện tại, chúng tôi đang triển khai và lập tài liệu đặc tả kiểm thử tích hợp.']),
  ('d31a5bd6-fc32-5b84-8982-2c1c533e0e13'::uuid, 0, 'mô tả, ghi, viết', '提案書に記載した通り、6月末に製品のデモを行います。', 'Như đã ghi trong đề xuất, chúng ta sẽ demo sản phẩm vào cuối tháng 6.', array['モバイル版開発で追加・変更する部分には、画面設計書に「追加」または「変更」と記載した。', 'リリースノートの記載内容に沿って説明いたします。'], array['Phần thêm/sửa ở bản mobile được ghi “Thêm” hoặc “Thay đổi” trong tài liệu thiết kế màn hình.', 'Tôi sẽ giải thích theo nội dung ghi trong release note.']),
  ('2cbc0866-fb3d-5c87-83d2-af73fd47fa1a'::uuid, 0, 'thích hợp, phù hợp (với)', 'この方法は、大きなプロジェクトに適しています。', 'Phương pháp này phù hợp với dự án lớn.', '{}'::text[], '{}'::text[]),
  ('a0421359-d41f-5570-a5f2-64856cd433de'::uuid, 0, 'ngôn ngữ lập trình', '皆さんにとっては、Cobolは難しいプログラミング言語だと思います。', 'Đối với các bạn, tôi nghĩ Cobol là một ngôn ngữ lập trình khó.', array['プログラミング言語がC#の場合は、この部署が担当するということですね。'], array['Nếu ngôn ngữ lập trình là C#, nghĩa là bộ phận này phụ trách, đúng không ạ?']),
  ('ba964b1d-edc2-5516-9ac2-39f5f15532da'::uuid, 0, 'quản lý chấm công/giờ làm', '２年前に勤怠管理システムを開発した。', 'Đã phát triển hệ thống quản lý chấm công hai năm trước.', array['現在、勤怠管理システムの設計と開発環境の構築を進めています。'], array['Hiện tại, chúng tôi đang tiến hành thiết kế hệ thống quản lý chấm công và xây dựng môi trường phát triển.']),
  ('a71537c4-2f4f-57be-a461-bf91dafe5812'::uuid, 0, 'chuyển thành bản mobile/thiết bị di động', '今回はそのシステムをベースに、モバイル化を行い、出退勤時間管理、打刻などの機能を追加・修正する。', 'Lần này dựa trên hệ thống đó để mobile hóa, thêm/sửa chức năng quản lý giờ vào-ra, chấm công…', array['「モバイル化_特別対応」のファイルについて、いくつか疑問点をまとめているので、会議の場で確認したい。'], array['Team đã tổng hợp một số điểm nghi vấn về file đó và muốn xác nhận ngay trong cuộc họp.']),
  ('2f9c79e7-cba4-51aa-9a63-00ffb8af83d0'::uuid, 0, 'giờ đến và giờ về', '今回はそのシステムをベースに、モバイル化を行い、出退勤時間管理、打刻などの機能を追加・修正する。', 'Lần này dựa trên hệ thống đó để mobile hóa, thêm/sửa chức năng quản lý giờ vào-ra, chấm công…', '{}'::text[], '{}'::text[]),
  ('2b11116b-082f-50e1-9914-f8e238ce5c20'::uuid, 0, 'chấm/quẹt thẻ chấm công', '今回はそのシステムをベースに、モバイル化を行い、出退勤時間管理、打刻などの機能を追加・修正する。', 'Lần này dựa trên hệ thống đó để mobile hóa, thêm/sửa chức năng quản lý giờ vào-ra, chấm công…', '{}'::text[], '{}'::text[]),
  ('f9c5ce58-4aeb-5bbc-8bca-85a111057039'::uuid, 0, 'các điểm cần chú ý', '注意事項を必ずお読みください。', 'Nhất định hãy đọc các điểm cần chú ý.', '{}'::text[], '{}'::text[]),
  ('3d960263-9b56-5e26-84df-5bd63ef64e68'::uuid, 0, 'xử lý, ứng phó', '「モバイル化_特別対応」のファイルについて、いくつか疑問点をまとめているので、会議の場で確認したい。', 'Team đã tổng hợp một số điểm nghi vấn về file đó và muốn xác nhận ngay trong cuộc họp.', array['弊社で対応の優先順位を決めて、連絡します。', '対応にかかる工数も見積もって報告してください。'], array['Công ty chúng tôi quyết định thứ tự ưu tiên xử lý rồi liên lạc.', 'Hãy ước tính cả công sức cần cho việc xử lý rồi báo cáo.']),
  ('a650860c-d112-5a27-87e5-569011b1727c'::uuid, 0, 'nhờ vả, yêu cầu', '確定すれば、クラウドの人材など要員追加を依頼することになると思います。', 'Khi được chốt, tôi nghĩ chúng tôi sẽ cần yêu cầu bổ sung nhân sự, như nhân lực cloud.', array['まだ確定していませんが、二週間後ぐらいにユーザ管理機能の修正を依頼するかもしれません。'], array['Tuy chưa chắc chắn nhưng khoảng hai tuần nữa có thể chúng tôi sẽ nhờ sửa chức năng quản lý người dùng.']),
  ('ffe5bf4c-f04f-577d-bccf-cc1abf36fd70'::uuid, 0, 'mỗi khi, từng lúc', '質問があれば、その都度お知らせください。', 'Nếu có câu hỏi, hãy cho tôi biết mỗi khi phát sinh.', '{}'::text[], '{}'::text[]),
  ('4438301b-6f32-564a-8084-d90323fc7aaa'::uuid, 0, 'trong khi, lúc đang/giữa chừng', '処理の途中でエラーが発生しました。', 'Lỗi đã xảy ra giữa chừng quá trình xử lý.', '{}'::text[], '{}'::text[]),
  ('680b1db0-2cb9-58ae-b9a9-6ce67ccafd47'::uuid, 0, 'bỏ qua (phần giải thích)', '時間がないので、この説明は飛ばします。', 'Vì không có thời gian nên tôi bỏ qua phần giải thích này.', '{}'::text[], '{}'::text[]),
  ('e716fe8c-9f61-586d-97ca-047029727479'::uuid, 0, 'buổi giải thích yêu cầu', 'プロジェクトのメンバーが全員そろいましたので、要件の説明会を始めたいと思います。', 'Vì toàn bộ thành viên dự án đã có mặt, tôi muốn bắt đầu buổi giải thích yêu cầu.', '{}'::text[], '{}'::text[]),
  ('fba560ec-dc1a-52ed-9f6d-f97ef944236d'::uuid, 0, 'hỏi ngay tại chỗ', '分からないことは、その場で質問してください。', 'Điều gì không hiểu hãy hỏi ngay tại chỗ.', '{}'::text[], '{}'::text[]),
  ('940e4685-8709-528a-b202-cdbe4a343307'::uuid, 0, 'thêm/sửa một phần chức năng', 'キックオフミーティングで説明した通り、一部機能の追加・修正を行います。', 'Như đã giải thích trong kickoff, chúng ta sẽ thêm/sửa một số chức năng.', array['このアプリをベースに、WebGLを使用してアプリをWeb化し、一部機能の追加・修正を行います。'], array['Dựa trên ứng dụng này, dùng WebGL để Web hóa ứng dụng và thêm/sửa một số chức năng.']),
  ('e1064b3c-24a5-58ab-8470-1ed38063a472'::uuid, 0, 'ngoài phạm vi Web hóa', '新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。', 'Tôi đã ghi thêm “Mới” cho màn hình mới và “Ngoài phạm vi Web hóa” cho phần không cần triển khai ở bản Web.', array['「新規」または「Web化対象外」の追記がない場合は、以前のアプリと同じ画面にするということですね。'], array['Nghĩa là nếu không có ghi thêm “Mới” hoặc “Ngoài phạm vi Web hóa”, thì sẽ dùng màn hình giống ứng dụng trước đây, đúng không ạ?']),
  ('794c6fc4-992f-56e6-ae4d-db58f6ae3081'::uuid, 0, 'ghi vào tài liệu thiết kế màn hình', '変更内容は画面設計書に記載します。', 'Nội dung thay đổi được ghi vào tài liệu thiết kế màn hình.', '{}'::text[], '{}'::text[]),
  ('f5c6c722-0259-5dc2-91b5-a55da147afe6'::uuid, 0, 'màn hình giống ứng dụng trước đó', '追記がない場合は、以前のアプリと同じ画面にするということですね。', 'Nếu không có ghi thêm, nghĩa là dùng màn hình giống ứng dụng trước đây, đúng không ạ?', '{}'::text[], '{}'::text[]),
  ('ec0706e7-dd70-5317-a08a-1048518ada8d'::uuid, 0, 'xác nhận điểm nghi vấn', '会議の前に、疑問点を確認します。', 'Trước cuộc họp, tôi xác nhận các điểm nghi vấn.', '{}'::text[], '{}'::text[]),
  ('5808c00c-dc9c-5be9-ab77-dc4fe48f88f4'::uuid, 0, 'nếu có gì trong lúc triển khai', '実装中に何かあったら、すぐに連絡してください。', 'Nếu có gì trong lúc triển khai, hãy liên lạc ngay.', '{}'::text[], '{}'::text[]),
  ('8809e642-045b-5ff9-8f08-3dac383a08e6'::uuid, 0, 'xử lý đặc biệt', 'この場合は、特別な対応が必要です。', 'Trường hợp này cần xử lý đặc biệt.', '{}'::text[], '{}'::text[]),
  ('a1d42ea2-ddaa-5505-bc91-68af743280e3'::uuid, 0, 'bỏ qua phần giải thích', '時間がないので、説明を飛ばしてもいいですか。', 'Vì không có thời gian, tôi bỏ qua phần giải thích được không?', '{}'::text[], '{}'::text[]),
  ('f139a5eb-e366-5de2-9d40-9712d643936e'::uuid, 0, 'cuộc họp trực tuyến', '来週はオンラインミーティングで打ち合わせをします。', 'Tuần sau chúng ta trao đổi qua họp trực tuyến.', '{}'::text[], '{}'::text[]),
  ('8fe342c1-d686-53db-82af-a395766b5ef0'::uuid, 0, 'gửi', '回答の詳細は、先週の木曜日に送付した資料をご確認ください。', 'Xin hãy xem tài liệu tôi đã gửi vào thứ Năm tuần trước để biết chi tiết câu trả lời.', array['昨日の夕方に、進捗の詳細をまとめた WBS と進捗報告書 を送付しました。'], array['Chiều hôm qua đã gửi WBS tổng hợp chi tiết tiến độ và báo cáo tiến độ.']),
  ('f532abf1-cc19-51c9-80ae-3fd07e4a30d7'::uuid, 0, 'kết quả thực tế', '先月の実績を報告します。', 'Tôi báo cáo kết quả thực tế của tháng trước.', '{}'::text[], '{}'::text[]),
  ('cbc6b402-ec1c-504f-a1ca-2ee2abae97c7'::uuid, 0, 'ghi chú, remark', '備考欄に補足を書いてください。', 'Hãy ghi phần bổ sung vào cột ghi chú.', '{}'::text[], '{}'::text[]),
  ('4a6c15a1-ef22-5b3b-9b7b-fdd3021a0700'::uuid, 0, 'môi trường', '現在、勤怠管理システムの設計と開発環境の構築を進めています。', 'Hiện tại, chúng tôi đang tiến hành thiết kế hệ thống quản lý chấm công và xây dựng môi trường phát triển.', array['セキュリティソフトと開発環境を設定する。', '環境構築は予定より4人日遅延しています。'], array['Cài phần mềm bảo mật và môi trường phát triển.', 'Việc xây dựng môi trường đang bị chậm 4 ngày công so với dự định.']),
  ('944990e4-1d9d-5972-8b0e-44bba011b52f'::uuid, 0, 'điều tra, khảo sát', '調査した結果、…すれば、解決することがわかりました。', 'Sau khi điều tra, chúng tôi biết rằng nếu … thì có thể giải quyết.', '{}'::text[], '{}'::text[]),
  ('aa900b2f-bb74-5ba0-94e3-19435e76b90a'::uuid, 0, 'xây dựng/thiết lập', '現在、勤怠管理システムの設計と開発環境の構築を進めています。', 'Hiện tại, chúng tôi đang tiến hành thiết kế hệ thống quản lý chấm công và xây dựng môi trường phát triển.', array['環境構築は予定より4人日遅延しています。'], array['Việc xây dựng môi trường đang bị chậm 4 ngày công so với dự định.']),
  ('5066ef82-53ec-5f25-9b0a-b3f771f80447'::uuid, 0, 'hiệu năng, performance', '理由はファイルにも書いた通り、RAMをたくさん使うことになり、パフォーマンスに影響を与える可能性があるからです。', 'Như đã ghi trong tệp, lý do là việc này có thể dùng nhiều RAM và ảnh hưởng đến hiệu năng.', '{}'::text[], '{}'::text[]),
  ('78a976d2-a403-5971-b64c-c9fb2b0d89a7'::uuid, 0, 'lưu, save', 'iPad版の学習データ保存機能では、お気に入り画面に画像が３枚以上あると、ページが再読み込みされます。', 'Ở chức năng lưu dữ liệu học của bản iPad, nếu màn hình Favorites có từ ba ảnh trở lên thì trang sẽ tải lại.', '{}'::text[], '{}'::text[]),
  ('0e02bfd8-cf71-5c8a-826f-1e1ee2958b93'::uuid, 0, 'chậm tiến độ', 'ここの遅延は来週中に取り戻す予定です。', 'Phần chậm này dự kiến được bù lại trong tuần sau.', array['環境構築は予定より4人日遅延しています。', 'このテストの遅延は遅くとも今月10日までに取り戻す予定です。'], array['Việc xây dựng môi trường đang bị chậm 4 ngày công so với dự định.', 'Phần chậm trễ của việc test này chúng tôi dự định sẽ khắc phục muộn nhất là ngày 10 tháng này.']),
  ('6a900195-2d67-5896-98e0-d04a37d419d9'::uuid, 0, 'tài liệu đặc tả kiểm thử', '現在は、実装と結合テスト仕様書作成を進めています。', 'Hiện tại, chúng tôi đang triển khai và lập tài liệu đặc tả kiểm thử tích hợp.', array['現在は、画面の実装 と 結合テスト仕様書作成 を進めています。'], array['Hiện đang triển khai màn hình và lập tài liệu đặc tả kiểm thử tích hợp.']),
  ('2d88a1ae-212c-59c6-aab6-e36547985c12'::uuid, 0, 'thuận lợi, suôn sẻ', '開発は順調に進んでいます。', 'Việc phát triển đang tiến triển thuận lợi.', '{}'::text[], '{}'::text[]),
  ('a6d56297-c152-5bba-b1b1-f23cb6bacae8'::uuid, 0, 'song song, đồng thời', '二つのタスクを並行して進めます。', 'Tôi tiến hành song song hai tác vụ.', '{}'::text[], '{}'::text[]),
  ('3d94615f-489d-5656-9860-b661e5f9b388'::uuid, 0, 'báo cáo tuần', '毎週金曜日に週報を提出します。', 'Thứ Sáu hằng tuần tôi nộp báo cáo tuần.', '{}'::text[], '{}'::text[]),
  ('b57e23d7-3487-5e5f-82c7-39ee2acfbe0a'::uuid, 0, 'đúng là, quả thật', '確かに、その通りですね。', 'Đúng là như vậy nhỉ.', '{}'::text[], '{}'::text[]),
  ('e2fa0b08-7b8c-5d82-98b2-d8d9a047c467'::uuid, 0, 'thủ tục', '必要な手続きを確認します。', 'Tôi xác nhận các thủ tục cần thiết.', '{}'::text[], '{}'::text[]),
  ('9e5c5ccb-bbac-5b43-8df9-79d77c311c82'::uuid, 0, 'chuẩn bị', '準備されたら、お声がけください。', 'Khi chuẩn bị xong, xin hãy gọi cho tôi.', array['今月末のエンドユーザとの会議に向けて、質問を準備しましょう。', '会議の準備をしている間に、Q&Aをリストアップしてあります。'], array['Hãy cùng chuẩn bị câu hỏi cho buổi họp cuối tháng này với end-user.', 'Trong lúc chuẩn bị cuộc họp, tôi đã liệt kê sẵn Q&A.']),
  ('3ff78402-baf2-59f8-817a-87c0f93a26df'::uuid, 0, '10%', '予定より１割ほど遅れています。', 'Đang chậm khoảng 10% so với dự kiến.', '{}'::text[], '{}'::text[]),
  ('ad542104-9ff3-5e55-9386-87ce01b05387'::uuid, 0, 'danh sách', 'そう言えば、先週相談した二つの機能は機能一覧に更新していただけましたか。', 'À, nhân tiện, hai chức năng đã trao đổi tuần trước, anh/chị đã cập nhật vào danh sách chức năng chưa ạ?', array['今朝、機能一覧の内容を変更しましたので、来週月曜日までにご確認いただけますか。'], array['Sáng nay chúng tôi đã thay đổi nội dung danh sách chức năng, anh/chị có thể xác nhận trước thứ Hai tuần sau không?']),
  ('703f8a62-d929-5ecc-b847-894ea354d351'::uuid, 0, 'sắp xếp, sort', '表のデータを並び替えてください。', 'Hãy sắp xếp lại dữ liệu trong bảng.', '{}'::text[], '{}'::text[]),
  ('1740be60-713d-5211-8bb0-f4b39d4789b5'::uuid, 0, 'yêu thích, favorite/bookmark', 'お気に入りに登録できる画像は最大２MBで10枚までです。', 'Hình ảnh có thể đăng ký trong phần Favorites tối đa là 10 tấm, dung lượng mỗi tấm không quá 2MB.', array['iPad版の学習データ保存機能では、お気に入り画面に画像が３枚以上あると、ページが再読み込みされます。'], array['Ở chức năng lưu dữ liệu học của bản iPad, nếu màn hình Favorites có từ ba ảnh trở lên thì trang sẽ tải lại.']),
  ('fd66454b-4b8a-5041-abc5-f285a0fcbf2b'::uuid, 0, 'bị ốm, sức khỏe không tốt', '体調不良のため、今日は休みます。', 'Vì sức khỏe không tốt nên hôm nay tôi nghỉ.', '{}'::text[], '{}'::text[]),
  ('fe15fd61-a118-5589-b2f0-a528b9798f43'::uuid, 0, 'ngày công', 'そのうち３人日はテスト工数です。', 'Trong đó 3 ngày công là effort kiểm thử.', array['環境構築は予定より4人日遅延しています。', '対応工数を見積もった結果、少なくとも10人日かかる見込みです。'], array['Việc xây dựng môi trường đang bị chậm 4 ngày công so với dự định.', 'Sau khi ước tính effort xử lý, dự kiến sẽ mất ít nhất 10 ngày công.']),
  ('28ca6ada-ae7c-5659-9775-92196b0a64fd'::uuid, 0, 'loại trừ, ngoại trừ', '土日を除いて、毎日出勤します。', 'Trừ thứ Bảy và Chủ Nhật, tôi đi làm mỗi ngày.', '{}'::text[], '{}'::text[]),
  ('50d67267-dc75-5cf2-8f97-c89c01714581'::uuid, 0, 'một lượt, đại khái/toàn bộ', '一通り確認しましたが、問題ありません。', 'Tôi đã xem qua một lượt, không có vấn đề.', '{}'::text[], '{}'::text[]),
  ('d6f8d9be-42f5-5c64-a1ba-ec4a7c0e9a0d'::uuid, 0, 'đối sách, biện pháp', 'お客様が課題と対策の内容について確認します。', 'Khách hàng xác nhận nội dung vấn đề và đối sách.', array['そうならないようにするために、対策してもらえますか。', '弊社で指定されているウイルス対策ソフトやメール誤送信防止ツールをインストールしましょう。'], array['Để không xảy ra như vậy, anh/chị có thể thực hiện biện pháp đối phó không?', 'Chúng ta sẽ cài phần mềm chống virus và công cụ ngăn gửi nhầm email do công ty chỉ định.']),
  ('f08437ea-7e16-5096-9d62-6910ae07ff07'::uuid, 0, 'thiếu bộ nhớ', 'メモリ不足が原因で、どのような状況が発生していますか。', 'Thiếu bộ nhớ gây ra tình huống nào?', array['メモリ不足が原因で、一部の画面が…動作しないのですね。'], array['Do thiếu bộ nhớ nên một số màn hình không hoạt động…, đúng không?']),
  ('80060bdd-f4d4-57c0-95e4-e8ee018fc5df'::uuid, 0, 'ảnh hưởng', '課題は全体の進捗に影響していますか。', 'Vấn đề có ảnh hưởng đến tiến độ chung không?', array['１点だけお願いですが、影響範囲についてもご検討ください。', 'それが、スケジュールに影響しそうなので、ご相談したいです。'], array['Tôi có một việc muốn nhờ: xin hãy cũng xem xét phạm vi ảnh hưởng.', 'Chính vì có vẻ sẽ ảnh hưởng đến lịch trình nên tôi muốn trao đổi.']),
  ('9153a82a-06b6-55f1-a0c8-026bafc27e20'::uuid, 0, 'dữ liệu tĩnh', '静的データはキャッシュに保存します。', 'Dữ liệu tĩnh được lưu vào cache.', '{}'::text[], '{}'::text[]),
  ('1a9e16ba-f5e0-503a-a669-a5cd026edd76'::uuid, 0, 'thao tác, hoạt động', 'メモリ不足が原因で、一部の画面が…動作しないのですね。', 'Do thiếu bộ nhớ nên một số màn hình không hoạt động…, đúng không?', array['機能は実行できますが、デスクトップ版と比べると動作が重くなります。', 'システムの動作確認に際して、インストールとアンインストールの手順を記載したドキュメントもレビューします。'], array['Chức năng vẫn chạy được, nhưng hoạt động chậm hơn so với bản desktop.', 'Khi kiểm tra hoạt động của hệ thống, chúng tôi cũng sẽ review cả tài liệu mô tả quy trình cài đặt và gỡ cài đặt.']),
  ('0491ee39-7a52-51c9-b986-2ce0c572163b'::uuid, 0, 'thay vào đó', '今回は、代わりに別の方法を使います。', 'Lần này chúng tôi dùng phương pháp khác thay vào đó.', '{}'::text[], '{}'::text[]),
  ('f344a810-2c37-5d03-ab03-a5ece3093d43'::uuid, 0, 'đưa lên làm sớm', 'これらのタスクは予定より2人日遅延していますが、…前倒しして対応しております。', 'Các task này chậm hai người-ngày so với kế hoạch, nhưng chúng tôi đang xử lý bằng cách đưa sớm …', '{}'::text[], '{}'::text[]),
  ('bdb8288d-1647-5a60-9f43-76dbed794398'::uuid, 0, 'bù lại, khắc phục phần chậm', 'ここの遅延は来週中に取り戻す予定です。', 'Phần chậm này dự kiến được bù lại trong tuần sau.', array['このテストの遅延は遅くとも今月10日までに取り戻す予定です。'], array['Phần chậm trễ của việc test này chúng tôi dự định sẽ khắc phục muộn nhất là ngày 10 tháng này.']),
  ('8ef98fe1-28db-5582-bc54-e89934d10e33'::uuid, 0, 'liên kết dữ liệu', 'システム間のデータ連携を確認します。', 'Tôi xác nhận việc liên kết dữ liệu giữa các hệ thống.', '{}'::text[], '{}'::text[]),
  ('134a7bb1-ef13-5cc5-be61-f9cc16f4c207'::uuid, 0, 'thiết kế cơ sở', '基本設計のレビューを行います。', 'Chúng tôi thực hiện review thiết kế cơ sở.', '{}'::text[], '{}'::text[]),
  ('3ab52f67-0614-522b-b32b-0af9a2f870c7'::uuid, 0, 'cáp biển', '海底ケーブルの工事で、通信が遅くなっています。', 'Do thi công cáp biển nên đường truyền bị chậm.', '{}'::text[], '{}'::text[]),
  ('6cd2c452-03c1-5c1d-8017-22b28e4a4319'::uuid, 0, 'hiểu nhầm', '要件を誤解したことが原因で、この機能を実装し直すのですね。', 'Nguyên nhân là do hiểu nhầm yêu cầu nên các bạn phải implement lại chức năng này nhỉ?', '{}'::text[], '{}'::text[]),
  ('b339c91d-7537-5731-8662-ee5d1c3a5cf2'::uuid, 0, 'tính khả thi', '技術的な実現可能性を調べます。', 'Tôi khảo sát tính khả thi về mặt kỹ thuật.', '{}'::text[], '{}'::text[]),
  ('3f68587c-3a04-5530-b6b6-0a970a12395f'::uuid, 0, 'đánh giá', '結果を評価して、報告書にまとめます。', 'Tôi đánh giá kết quả rồi tổng hợp vào báo cáo.', '{}'::text[], '{}'::text[]),
  ('8cae80b7-aea9-5fc6-9a95-903bb866b96f'::uuid, 0, 'bố cục màn hình', '画面レイアウトはこれでよいかご確認お願いします。', 'Xin quý công ty xác nhận bố cục màn hình như vậy đã được chưa.', '{}'::text[], '{}'::text[]),
  ('7ddcdc85-b955-5920-8f8c-c96ee40322f2'::uuid, 0, 'test case, hạng mục kiểm thử', '試験項目を洗い出しました。', 'Tôi đã liệt kê các hạng mục kiểm thử.', '{}'::text[], '{}'::text[]),
  ('5f562ea5-4a32-5dda-af8a-b52797179887'::uuid, 0, 'thiết bị đầu cuối', 'そこで、端末のRAMは４GB以上を推奨しています。', 'Vì vậy, chúng tôi khuyến nghị RAM của thiết bị từ 4GB trở lên.', array['見積りの際に説明した通り、端末のスペックによるものです。', '見積りの際に説明した通り、端末のハードウェアのスペックによるものです。'], array['Như đã giải thích khi báo giá, nguyên nhân là do cấu hình của thiết bị.', 'Đúng như đã giải thích khi báo giá, đây là do cấu hình phần cứng của thiết bị.']),
  ('98ee6d5f-3277-59b6-88f9-d8bfeb021297'::uuid, 0, 'kiểm thử tải', 'リリース前に負荷テストを行います。', 'Trước khi release sẽ thực hiện kiểm thử tải.', '{}'::text[], '{}'::text[]),
  ('ee4a067c-d4ff-559b-bdf9-fbd234348d3f'::uuid, 0, 'xử lý batch/hàng loạt', 'バッチ処理に加えて、画面処理も担当することになりました。', 'Ngoài xử lý batch, tôi còn được phân công phụ trách cả xử lý màn hình.', '{}'::text[], '{}'::text[]),
  ('f6c09461-cff5-59e5-a811-c1d99b9c2279'::uuid, 0, 'cân nhắc', 'ユーザーの使いやすさも考慮して設計します。', 'Chúng tôi thiết kế có cân nhắc cả sự dễ sử dụng cho người dùng.', '{}'::text[], '{}'::text[]),
  ('317e2ada-a326-54d9-8575-d96dda975962'::uuid, 0, 'khắc phục, lấy lại phần chậm', '遅れを挽回するために、作業を前倒しします。', 'Để lấy lại phần chậm, chúng tôi đẩy sớm công việc.', '{}'::text[], '{}'::text[]),
  ('70c93188-cd01-54b9-95f9-f43da4c3ab81'::uuid, 0, 'thông báo, báo tin', '状況が分かったら、一報をお願いします。', 'Khi nắm được tình hình, xin hãy báo tin.', '{}'::text[], '{}'::text[]),
  ('1bc1cd6f-5adf-52a7-9fcc-340361fc4295'::uuid, 0, 'vấn đề phát sinh', '開発中に課題が発生しました。', 'Vấn đề đã phát sinh trong lúc phát triển.', '{}'::text[], '{}'::text[]),
  ('02e2af6c-9cd2-5b05-9f60-87552fd8c792'::uuid, 0, 'do thiếu bộ nhớ nên…', 'メモリ不足が原因で、アプリが停止しました。', 'Ứng dụng bị dừng do thiếu bộ nhớ.', '{}'::text[], '{}'::text[]),
  ('99e4b831-a4dc-53f5-9a77-9d5c603f2343'::uuid, 0, 'lưu dữ liệu tĩnh vào RAM', '静的データをRAMに保存すると、動作が速くなります。', 'Lưu dữ liệu tĩnh vào RAM thì hoạt động nhanh hơn.', '{}'::text[], '{}'::text[]),
  ('c0cc0c90-cbb3-515d-8767-78fb181472d4'::uuid, 0, 'lưu dữ liệu vào indexedDB', 'ブラウザのindexedDBにデータを保存します。', 'Tôi lưu dữ liệu vào indexedDB của trình duyệt.', '{}'::text[], '{}'::text[]),
  ('a3328d54-e577-5752-865e-4f8209224e4d'::uuid, 0, 'chậm hai người-ngày so với dự kiến', '作業が予定より2人日遅延しています。', 'Công việc đang chậm 2 người-ngày so với dự kiến.', '{}'::text[], '{}'::text[]),
  ('aa6ca493-ce2f-56c6-9324-e24ab1ecc891'::uuid, 0, 'bù lại phần chậm trễ', '週末に作業して、遅延を取り戻します。', 'Làm việc cuối tuần để bù lại phần chậm trễ.', '{}'::text[], '{}'::text[]),
  ('1839a0ab-7498-5c87-88ea-6961b22689ee'::uuid, 0, 'xử lý bằng cách đẩy một việc lên sớm', '一部の作業を前倒しして対応します。', 'Xử lý bằng cách đẩy một phần công việc lên sớm.', '{}'::text[], '{}'::text[]),
  ('9351b430-d339-53b1-9c4a-556759e6358b'::uuid, 0, 'ảnh hưởng đến tiến độ chung', 'この遅れは、全体の進捗に影響します。', 'Sự chậm trễ này ảnh hưởng đến tiến độ chung.', '{}'::text[], '{}'::text[]),
  ('78e681ba-123a-5bc7-afc1-5b05e52ffe6e'::uuid, 0, 'nếu có vấn đề khác, vui lòng liên lạc', '本日の報告は以上です。また何か問題があれば、ご連絡お願いします。', 'Báo cáo hôm nay đến đây. Nếu có vấn đề khác, vui lòng liên lạc.', '{}'::text[], '{}'::text[]),
  ('e22253eb-a91d-512e-9841-73a5a41c5466'::uuid, 0, 'vui lòng báo lại một tin', '結果が出たら、一報ください。', 'Khi có kết quả, xin hãy báo tin.', '{}'::text[], '{}'::text[]),
  ('33b716ba-25e7-5dd3-852f-fb334e4bf366'::uuid, 0, 'thiết lập giới hạn', 'なぜチームは、ブラウザでアプリを開くときの操作に制限を設けたいのですか。', 'Vì sao nhóm muốn đặt giới hạn thao tác khi mở ứng dụng trên trình duyệt?', array['ブラウザでアプリを開くときに、複数のタブやウィンドウで開けないように制限を設けたいです。', 'そこで、ご相談ですが、今回のリリースは制限を設けたバージョンを納品し、次回のリリースの際に制限なしのバージョンを納品したいです。'], array['Khi mở ứng dụng trên trình duyệt, chúng tôi muốn đặt giới hạn để không thể mở ở nhiều tab hoặc cửa sổ.', 'Vì vậy, tôi muốn trao đổi: ở lần release này, chúng tôi muốn giao bản có giới hạn; đến lần release sau sẽ giao bản không giới hạn.']),
  ('87842be3-1143-5540-9afb-68cc25b8a67c'::uuid, 0, 'thêm, bổ sung', '４件の質問を追加しましたので、金曜日までにご回答いただけますか。', 'Chúng tôi đã thêm bốn câu hỏi, anh/chị có thể trả lời trước thứ Sáu không?', array['昨日、Q&Aファイルに５番〜８番の４件の質問を追加しましたので、今週金曜日までにご回答いただけますか。', 'クラウドの人材など、要員追加が必要になると思います。'], array['Hôm qua chúng tôi đã bổ sung bốn câu hỏi từ số 5 đến số 8 vào tệp Q&A. Quý công ty có thể trả lời trước thứ Sáu tuần này không ạ?', 'Có thể sẽ cần bổ sung nhân lực, ví dụ nhân sự cloud.']),
  ('86233a9d-bb1c-50c5-bddc-680be6caa2ea'::uuid, 0, 'phạm vi', 'すぐ確認して、回答できる範囲で回答していただけますか。', 'Xin hãy xác nhận ngay và trả lời trong phạm vi có thể.', array['すぐ確認して、回答できる範囲で回答したいですが、いかがですか。', '１点だけお願いですが、影響範囲についてもご検討ください。'], array['Tôi muốn kiểm tra ngay và trả lời trong phạm vi có thể, có được không?', 'Tôi có một việc muốn nhờ: xin hãy cũng xem xét phạm vi ảnh hưởng.']),
  ('94426cd6-77d1-516d-9b98-d0ca77a58546'::uuid, 0, 'chuyển đổi', '新しいバージョンに切り替えます。', 'Tôi chuyển sang phiên bản mới.', '{}'::text[], '{}'::text[]),
  ('b3f6b062-aa71-5f4d-95c4-9aa926ad0eb2'::uuid, 0, 'mới nhất', 'バージョンは、最新のものだけでよいです。', 'Chỉ cần phiên bản mới nhất.', '{}'::text[], '{}'::text[]),
  ('c33d9dfd-2ca0-56ca-a54e-df135a15fa5c'::uuid, 0, 'thao tác', 'お客様は、アプリの操作について何と言っていますか。', 'Khách hàng nói gì về thao tác sử dụng ứng dụng?', array['アプリを操作するときの動きについて相談させてください。', '操作には制限をかけたくないのですが、社内で確認してから回答します。'], array['Tôi muốn trao đổi về hành vi khi thao tác ứng dụng.', 'Tôi không muốn đặt giới hạn cho thao tác, nhưng tôi sẽ xác nhận nội bộ rồi trả lời.']),
  ('a46ff610-0e31-5686-b99f-a0f791d774e0'::uuid, 0, 'hoạt động, chuyển động', 'アプリを操作するときの動きについて相談させてください。', 'Tôi muốn trao đổi về hành vi khi thao tác ứng dụng.', '{}'::text[], '{}'::text[]),
  ('5aa300a1-086f-5d3d-ad7f-f885159e5b22'::uuid, 0, 'nhiều, nhiều hơn một', 'ブラウザでアプリを開くときに、複数のタブやウィンドウで開けないように制限を設けたいです。', 'Khi mở ứng dụng trên trình duyệt, chúng tôi muốn đặt giới hạn để không thể mở ở nhiều tab hoặc cửa sổ.', array['修正した箇所を複数の環境でテストするわけにはいかないですか。', '同じブラウザで複数ウィンドウを開くのに制限をかけない、というご要望でしたが、これに対応するには予定よりも時間がかかりそうです。'], array['Không thể kiểm thử phần đã sửa trên nhiều môi trường được sao?', 'Quý công ty có yêu cầu không đặt giới hạn khi mở nhiều cửa sổ trong cùng trình duyệt, nhưng để đáp ứng yêu cầu này có vẻ sẽ mất nhiều thời gian hơn dự kiến.']),
  ('1b7776e8-5e33-567c-b21e-238aa7b4ff01'::uuid, 0, 'gây ảnh hưởng', '理由はテスト工数が増えることになり、プロジェクトのコストに影響を与える可能性があるからです。', 'Lý do là sẽ làm tăng effort kiểm thử và có thể ảnh hưởng đến chi phí của dự án.', array['理由はファイルにも書いた通り、RAMをたくさん使うことになり、パフォーマンスに影響を与える可能性があるからです。'], array['Như đã ghi trong tệp, lý do là việc này có thể dùng nhiều RAM và ảnh hưởng đến hiệu năng.']),
  ('81237e4e-c160-5835-a86d-b853dea2e89f'::uuid, 0, 'đặt giới hạn', '操作には制限をかけたくないのですが、社内で確認してから回答します。', 'Tôi không muốn đặt giới hạn cho thao tác, nhưng tôi sẽ xác nhận nội bộ rồi trả lời.', array['制限をかけないように対応した場合は、今回のリリースに間に合わないと思っています。', '制限をかけない、というご要望でしたが、これに対応するには予定よりも時間がかかりそうです。'], array['Nếu xử lý để không đặt giới hạn, tôi nghĩ sẽ không kịp lần release này.', 'Về yêu cầu không thiết lập hạn chế, để xử lý việc này có vẻ sẽ mất thời gian hơn so với dự kiến.']),
  ('9921574b-9255-58e4-a80c-eb4f1020a963'::uuid, 0, 'trong công ty', '社内で確認してから回答します。', 'Tôi sẽ xác nhận nội bộ rồi trả lời.', array['まずは社内で検討し、後ほど改めて連絡させていただきます。', '会議室は社内の会議室予約サイトから予約する。'], array['Trước hết chúng tôi sẽ xem xét nội bộ, sau đó sẽ liên hệ lại.', 'Đặt phòng qua trang đặt phòng nội bộ.']),
  ('06ca2cb9-a2b9-5840-b898-385b6ec20f7d'::uuid, 0, 'kết thúc', 'そろそろ終了時間ですので、残りの質問を含めて、今週中に回答していただけると幸いです。', 'Sắp hết giờ, vì vậy chúng tôi rất mong nhận được câu trả lời cho cả các câu hỏi còn lại trong tuần này.', '{}'::text[], '{}'::text[]),
  ('955a4b5f-080d-5845-b0bd-eb5acaa3ac7d'::uuid, 0, 'phần còn lại', 'そろそろ終了時間ですので、残りの質問を含めて、今週中に回答していただけると幸いです。', 'Sắp hết giờ, vì vậy chúng tôi rất mong nhận được câu trả lời cho cả các câu hỏi còn lại trong tuần này.', '{}'::text[], '{}'::text[]),
  ('7c58eaf9-c410-5cb0-97a6-0b7dc255f1bd'::uuid, 0, 'sẽ rất cảm kích nếu…', 'そろそろ終了時間ですので、残りの質問を含めて、今週中に回答していただけると幸いです。', 'Sắp hết giờ, vì vậy chúng tôi rất mong nhận được câu trả lời cho cả các câu hỏi còn lại trong tuần này.', '{}'::text[], '{}'::text[]),
  ('85882a5b-aa6c-5db7-a62f-5aef3e0d6263'::uuid, 0, 'ngay, sớm', '早急に対応をお願いします。', 'Xin hãy xử lý sớm.', '{}'::text[], '{}'::text[]),
  ('d7bc69b2-0e97-59be-9c70-9ab3fd9414a0'::uuid, 0, 'khẩn cấp', '緊急の場合は、電話で連絡してください。', 'Trường hợp khẩn cấp, hãy liên lạc qua điện thoại.', '{}'::text[], '{}'::text[]),
  ('03b1bff8-3d9a-5979-984d-4639a0f21b0a'::uuid, 0, 'mong muốn', '詳細画面のレイアウトについて、お客様は何を希望していますか。', 'Về bố cục màn hình chi tiết, khách hàng mong muốn điều gì?', '{}'::text[], '{}'::text[]),
  ('fab95c62-a28c-537d-8dc7-90b92d62c30c'::uuid, 0, 'hành vi khách hàng', '顧客行動のデータを分析します。', 'Tôi phân tích dữ liệu hành vi khách hàng.', '{}'::text[], '{}'::text[]),
  ('259414b7-88c6-5d41-bddb-f3edebe9eab2'::uuid, 0, 'chuyển đổi, migrate', 'メールでお知らせした通り、12月にWeb版への移行の受け入れテストを行う見込みです。', 'Như đã thông báo qua email, dự kiến vào tháng 12 sẽ thực hiện kiểm thử nghiệm thu việc chuyển sang bản Web.', '{}'::text[], '{}'::text[]),
  ('b9a0d57e-e2b3-58e2-a15c-74814d5b3ad2'::uuid, 0, 'like (mạng xã hội)', '投稿に「いいね！」をつけました。', 'Tôi đã bấm "thích" cho bài đăng.', '{}'::text[], '{}'::text[]),
  ('3efa0ead-dda8-5650-b55f-3729aa844afb'::uuid, 0, 'đưa vào sử dụng', 'ウイルス対策ソフトのDefenderを導入するというご要望でしたが、これに対応するにはIT部長の承認が必要になりそうです。', 'Yêu cầu là đưa vào phần mềm chống virus Defender, nhưng để đáp ứng việc này có vẻ cần sự phê duyệt của trưởng bộ phận IT.', '{}'::text[], '{}'::text[]),
  ('7ce49abd-7c87-5c60-90ca-981868afb7c0'::uuid, 0, 'để chắc chắn', 'そこで、不具合が出た場合の体制について、念のためもう一度聞かせてください。', 'Vì vậy, cho tôi hỏi lại để chắc chắn về cơ chế khi có lỗi.', '{}'::text[], '{}'::text[]),
  ('26d9b52e-314a-5e9e-a00b-a008603bb878'::uuid, 0, 'trước và sau', '作業の前後に、必ずバックアップを取ります。', 'Trước và sau công việc, tôi luôn sao lưu.', '{}'::text[], '{}'::text[]),
  ('c4dd8f31-effd-51b4-a4cb-60ab3bfa32fa'::uuid, 0, 'ngại/áy náy vì làm phiền', 'お忙しいところ恐縮ですが、お願いがございます。', 'Xin lỗi đã làm phiền khi anh/chị bận, tôi có một việc muốn nhờ.', '{}'::text[], '{}'::text[]),
  ('0a39dd85-77d8-59ec-8c92-f4e8134d5801'::uuid, 0, 'một lần nữa; sau đó', 'まずは社内で検討し、後ほど改めて連絡させていただきます。', 'Trước hết chúng tôi sẽ xem xét nội bộ, sau đó sẽ liên hệ lại.', '{}'::text[], '{}'::text[]),
  ('64d3c20b-c499-5306-85d1-99faddf94b22'::uuid, 0, 'tệp hỏi và đáp', 'はい、ではQ&Aファイルを映しますので、少しお待ちください。', 'Vâng, vậy tôi sẽ hiển thị tệp Q&A, xin vui lòng chờ một chút.', array['Q&Aファイルに関して、チームはいつまでに回答を受け取りたいですか。', '昨日、Q&Aファイルに５番〜８番の４件の質問を追加しましたので、今週金曜日までにご回答いただけますか。'], array['Nhóm muốn nhận câu trả lời cho tệp Q&A trước khi nào?', 'Hôm qua chúng tôi đã bổ sung bốn câu hỏi từ số 5 đến số 8 vào tệp Q&A. Quý công ty có thể trả lời trước thứ Sáu tuần này không ạ?']),
  ('ad6f3713-0434-5b7b-a7aa-81d791006ed5'::uuid, 0, 'phiên bản mới nhất', '最新のバージョンをダウンロードしてください。', 'Hãy tải phiên bản mới nhất.', '{}'::text[], '{}'::text[]),
  ('ec79eaa9-04a5-51bd-bf38-1c9b2d5b8d98'::uuid, 0, 'phiên bản ngay trước đó', '問題があれば、一つ前のバージョンに戻します。', 'Nếu có vấn đề thì quay về phiên bản ngay trước đó.', '{}'::text[], '{}'::text[]),
  ('e6c84ac7-b4d2-53a1-9b90-ca1f6e6c9451'::uuid, 0, 'trình duyệt kiểm thử', 'テストブラウザでは、正しく表示されました。', 'Trên trình duyệt kiểm thử, nó hiển thị đúng.', '{}'::text[], '{}'::text[]),
  ('5f254eeb-1932-5aa6-a584-04f2ba7ee4c3'::uuid, 0, 'nhiều tab hoặc cửa sổ', 'ブラウザでアプリを開くときに、複数のタブやウィンドウで開けないように制限を設けたいです。', 'Khi mở ứng dụng trên trình duyệt, chúng tôi muốn đặt giới hạn để không thể mở ở nhiều tab hoặc cửa sổ.', '{}'::text[], '{}'::text[]),
  ('ecbdd16b-1aa2-5832-b3c9-b6c7bd9607c7'::uuid, 0, 'ảnh hưởng đến hiệu năng', '理由はファイルにも書いた通り、RAMをたくさん使うことになり、パフォーマンスに影響を与える可能性があるからです。', 'Như đã ghi trong tệp, lý do là việc này có thể dùng nhiều RAM và ảnh hưởng đến hiệu năng.', '{}'::text[], '{}'::text[]),
  ('552c372a-828b-50b2-8cdd-6fbfab577b52'::uuid, 0, 'phạm vi có thể trả lời', 'すぐ確認して、回答できる範囲で回答していただけますか。', 'Xin hãy xác nhận ngay và trả lời trong phạm vi có thể.', array['すぐ確認して、回答できる範囲で回答したいですが、いかがですか。'], array['Tôi muốn kiểm tra ngay và trả lời trong phạm vi có thể, có được không?']),
  ('ded12902-2190-56d2-909e-7dc9773b752c'::uuid, 0, 'các câu hỏi còn lại', 'そろそろ終了時間ですので、残りの質問を含めて、今週中に回答していただけると幸いです。', 'Sắp hết giờ, vì vậy chúng tôi rất mong nhận được câu trả lời cho cả các câu hỏi còn lại trong tuần này.', '{}'::text[], '{}'::text[]),
  ('5514b285-7ef1-558b-8431-16c019d08a48'::uuid, 0, 'xác nhận nội bộ rồi trả lời', '社内で確認してから回答します。', 'Tôi sẽ xác nhận nội bộ rồi trả lời.', '{}'::text[], '{}'::text[]),
  ('a2f42293-c59d-5bae-9ea3-3a34dad4af68'::uuid, 0, 'đặt, bố trí', '詳細画面では、要件通り、画像を上部に配置しています。', 'Ở màn hình chi tiết, theo đúng yêu cầu, chúng tôi đặt ảnh ở phía trên.', array['まず、納品物ですが、ソースコードとソースコードからビルドしたアプリケーション、そして、ドキュメントをこちらのフォルダに配置しました。'], array['Trước tiên về deliverable, chúng tôi đã đặt source code, ứng dụng build từ source code và tài liệu vào thư mục này.']),
  ('5bcdf1a0-6fb0-5b20-aa85-45fc4f8da5ca'::uuid, 0, 'chồng lên', 'やはり、画像にボタンが重なってしまうのは避けたいですね。', 'Quả nhiên, chúng tôi muốn tránh việc nút bị chồng lên ảnh.', array['ボタンが画像に重ならないように、表示領域を小さくして対応することはできますが、いかがですか。', 'そうですね…。ボタンが重ならないように、画像の表示領域を小さくして対応することはできますが、いかがですか。'], array['Để nút không chồng lên ảnh, chúng tôi có thể xử lý bằng cách thu nhỏ vùng hiển thị; như vậy có được không?', 'Vâng… Để nút không chồng lên ảnh, chúng tôi có thể xử lý bằng cách thu nhỏ vùng hiển thị ảnh; như vậy có được không ạ?']),
  ('9e5bdbf1-39e4-5df2-bba3-491e0e4f7bce'::uuid, 0, 'tránh', 'やはり、画像にボタンが重なってしまうのは避けたいですね。', 'Quả nhiên, chúng tôi muốn tránh việc nút bị chồng lên ảnh.', '{}'::text[], '{}'::text[]),
  ('fbf69bf2-501f-5d3f-9d6a-8192cf0303f7'::uuid, 0, 'vùng, khu vực', '可能であれば、表示領域は変更しないようにしたいです。', 'Nếu có thể, tôi muốn không thay đổi vùng hiển thị.', array['ボタンが画像に重ならないように、表示領域を小さくして対応することはできますが、いかがですか。', 'そうですね…。ボタンが重ならないように、画像の表示領域を小さくして対応することはできますが、いかがですか。'], array['Để nút không chồng lên ảnh, chúng tôi có thể xử lý bằng cách thu nhỏ vùng hiển thị; như vậy có được không?', 'Vâng… Để nút không chồng lên ảnh, chúng tôi có thể xử lý bằng cách thu nhỏ vùng hiển thị ảnh; như vậy có được không ạ?']),
  ('16f37366-09ae-56ce-bf2b-9fda6df287c9'::uuid, 0, 'mặc định', 'デフォルトの画像サイズを小さくして、対応するわけにはいかないですか。', 'Không thể xử lý bằng cách thu nhỏ kích thước ảnh mặc định được sao?', '{}'::text[], '{}'::text[]),
  ('9b167903-d79c-566f-960d-3c4312de3d5f'::uuid, 0, 'khung hiển thị', '実は、アプリの表示枠は画面の縦横の比率に固定しているので、その案での対応は難しいかと思います。', 'Thực ra, khung hiển thị của ứng dụng được cố định theo tỷ lệ ngang dọc của màn hình, nên tôi nghĩ việc xử lý theo phương án đó có thể khó.', '{}'::text[], '{}'::text[]),
  ('6896b9d8-5242-5993-b661-cb2dcb0bace3'::uuid, 0, 'tỷ lệ ngang dọc', '実は、アプリの表示枠は画面の縦横の比率に固定しているので、その案での対応は難しいかと思います。', 'Thực ra, khung hiển thị của ứng dụng được cố định theo tỷ lệ ngang dọc của màn hình, nên tôi nghĩ việc xử lý theo phương án đó có thể khó.', '{}'::text[], '{}'::text[]),
  ('63e9c462-27ab-5231-9c1d-cdf843108f29'::uuid, 0, 'cố định', '実は、アプリの表示枠は画面の縦横の比率に固定しているので、その案での対応は難しいかと思います。', 'Thực ra, khung hiển thị của ứng dụng được cố định theo tỷ lệ ngang dọc của màn hình, nên tôi nghĩ việc xử lý theo phương án đó có thể khó.', '{}'::text[], '{}'::text[]),
  ('8340726d-1d41-554f-92c2-a2f30acb68f8'::uuid, 0, 'phương án', '別の案を検討しましょう。', 'Hãy xem xét phương án khác.', '{}'::text[], '{}'::text[]),
  ('7f5e04b2-4b8a-567b-be1b-7b0dd097f938'::uuid, 0, 'mang về xem xét', 'では、一度持ち帰って、技術的に実現可能か検討してみます。', 'Vậy chúng tôi sẽ mang việc này về xem xét tính khả thi kỹ thuật.', '{}'::text[], '{}'::text[]),
  ('32cc27f7-0fad-5bc1-9ba6-11d112b604f9'::uuid, 0, 'ước tính', '対応にかかる工数も見積もって報告してください。', 'Hãy ước tính cả công sức cần cho việc xử lý rồi báo cáo.', array['対応工数を見積もった結果、少なくとも10人日かかる見込みです。'], array['Sau khi ước tính effort xử lý, dự kiến sẽ mất ít nhất 10 ngày công.']),
  ('9cd51276-abd8-5663-879e-0e8243e21f51'::uuid, 0, 'phóng to', '画像を拡大して、確認します。', 'Tôi phóng to hình ảnh để xác nhận.', '{}'::text[], '{}'::text[]),
  ('5af2019b-57f2-561b-a993-e17520d53df9'::uuid, 0, 'thu nhỏ', '画面を縮小すると、全体が見えます。', 'Thu nhỏ màn hình thì thấy được toàn bộ.', '{}'::text[], '{}'::text[]),
  ('6b29289f-120b-5a2c-8147-70eb7e665621'::uuid, 0, 'sự cố', '１点確認しておきたいのですが、インシデント情報をまとめて田中さんに報告する、という理解でよろしいでしょうか。', 'Có một điểm tôi muốn xác nhận: tôi hiểu là sẽ tổng hợp thông tin sự cố rồi báo cáo cho anh Tanaka, như vậy có đúng không ạ?', '{}'::text[], '{}'::text[]),
  ('300f83cc-e6c6-52b2-83ed-82ded919fa4e'::uuid, 0, 'tính nhất quán', 'データの整合性を確認します。', 'Tôi kiểm tra tính nhất quán của dữ liệu.', '{}'::text[], '{}'::text[]),
  ('dfc94aeb-4502-5ad0-806b-54820b289a13'::uuid, 0, 'bảo đảm', 'テスト環境を確保しました。', 'Tôi đã chuẩn bị (đảm bảo) được môi trường kiểm thử.', '{}'::text[], '{}'::text[]),
  ('bad9fdf2-6787-574f-8b8a-d5e021c12ec0'::uuid, 0, 'phát triển nội bộ', 'このツールは自社開発です。', 'Công cụ này do công ty tự phát triển.', '{}'::text[], '{}'::text[]),
  ('b6ef100f-fe57-5dcd-85b0-74fcfd324f84'::uuid, 0, 'kiểm chứng, kiểm tra', '修正が正しいか、検証します。', 'Tôi kiểm chứng xem việc sửa có đúng không.', '{}'::text[], '{}'::text[]),
  ('d0202326-a757-548c-9122-d803e80d68c5'::uuid, 0, 'suôn sẻ', '円滑にコミュニケーションを取るために、毎日会議をします。', 'Để giao tiếp suôn sẻ, chúng tôi họp mỗi ngày.', '{}'::text[], '{}'::text[]),
  ('cac03018-def5-57f8-b44c-4e19fb3a9f18'::uuid, 0, 'xem xét lại', '今後のプロジェクトに向けて見直すべきところについても検討しましょう。', 'Hãy cùng xem xét các điểm cần rà soát cho các dự án sắp tới.', '{}'::text[], '{}'::text[]),
  ('ed5fcd36-78ad-5300-9c8b-fb4d4469908d'::uuid, 0, 'điều tra làm rõ', 'エラーの原因を究明します。', 'Tôi điều tra làm rõ nguyên nhân lỗi.', '{}'::text[], '{}'::text[]),
