  ('6e50b6bd-1bb4-5c43-ad62-e902f1467ead'::uuid, 0, 'công sức cần cho việc xử lý', '対応にかかる工数も見積もって報告してください。', 'Hãy ước tính cả công sức cần cho việc xử lý rồi báo cáo.', '{}'::text[], '{}'::text[]),
  ('041d672d-bad3-5696-a600-3a4e9c4dc2fe'::uuid, 0, 'điểm thay đổi và công sức thay đổi', '変更点と変更の工数を報告します。', 'Tôi báo cáo điểm thay đổi và công sức thay đổi.', '{}'::text[], '{}'::text[]),
  ('f2a6191c-5382-5465-a033-a8f708b6a4c6'::uuid, 0, 'dễ phân biệt với màu nền', 'この色は、背景色と区別しやすいです。', 'Màu này dễ phân biệt với màu nền.', '{}'::text[], '{}'::text[]),
  ('b57b55fb-945a-5ca3-8ebb-8d28fc6a5763'::uuid, 0, 'đang thống nhất với các màn hình khác', 'このボタンは、他の画面と統一しているため、変更できません。', 'Nút này thống nhất với các màn hình khác nên không thể thay đổi.', '{}'::text[], '{}'::text[]),
  ('520e3097-9b4b-500c-99d3-be02eb2a0f07'::uuid, 0, 'bắt chuyện, liên hệ', '困ったときは、いつでも声をかけてください。', 'Khi gặp khó khăn, cứ gọi cho tôi bất cứ lúc nào.', '{}'::text[], '{}'::text[]),
  ('2c6a1b71-7104-56c5-a34e-ef7246bfe588'::uuid, 0, 'giao hàng, bàn giao', '制限なしのバージョンを納品したいです。', 'Chúng tôi muốn giao bản không giới hạn.', array['制限なしのバージョンの納品、予めご了承くださいませんか。', '制限なしのバージョンを納品する予定ですが、ご承諾いただけますか。'], array['Về việc giao bản không giới hạn, quý công ty có thể thông cảm/chấp thuận trước không?', 'Chúng tôi dự định giao bản không giới hạn; quý công ty có thể đồng ý không?']),
  ('b628dd75-6030-5cd0-98c3-28a0f9a8235d'::uuid, 0, 'đồng ý, nhất trí', 'チームは次回のリリースで制限なしのバージョンを納品することを提案しましたが、お客様は合意しましたか。', 'Nhóm đã đề xuất giao bản không giới hạn ở lần release sau, vậy khách hàng có đồng ý không?', '{}'::text[], '{}'::text[]),
  ('c9c538a1-26df-572a-9a14-6dd214117217'::uuid, 0, 'mong muốn, yêu cầu', '制限をかけない、というご要望でしたが、これに対応するには予定よりも時間がかかりそうです。', 'Về yêu cầu không thiết lập hạn chế, để xử lý việc này có vẻ sẽ mất thời gian hơn so với dự kiến.', array['ウイルス対策ソフトのDefenderを導入するというご要望でしたが、これに対応するにはIT部長の承認が必要になりそうです。', 'ご要望に応じて、今回の修正対象外の点についても追記しています。'], array['Yêu cầu là đưa vào phần mềm chống virus Defender, nhưng để đáp ứng việc này có vẻ cần sự phê duyệt của trưởng bộ phận IT.', 'Theo mong muốn của quý vị, chúng tôi cũng ghi bổ sung những điểm nằm ngoài phạm vi sửa lần này.']),
  ('7d9e16ab-a033-52d3-a201-bbc2ed129e5e'::uuid, 0, 'release, phát hành', '時間がかかるということですが、今回のリリーススケジュールには影響しますか。', 'Anh/chị nói sẽ mất thời gian, vậy có ảnh hưởng đến lịch release lần này không?', array['制限をかけないように対応した場合は、今回のリリースに間に合わないと思っています。', 'チームは次回のリリースで制限なしのバージョンを納品することを提案しましたが、お客様は合意しましたか。'], array['Nếu xử lý để không đặt giới hạn, tôi nghĩ sẽ không kịp lần release này.', 'Nhóm đã đề xuất giao bản không giới hạn ở lần release sau, vậy khách hàng có đồng ý không?']),
  ('d409d539-b2a9-520d-8a9e-56a29dc9d2cc'::uuid, 0, 'kịp thời hạn', '来週の始めに機器を準備した場合は、テストに間に合わないと思います。', 'Nếu đầu tuần sau mới chuẩn bị thiết bị thì tôi nghĩ sẽ không kịp cho việc kiểm thử.', array['制限をかけないように対応した場合は、今回のリリースに間に合わないと思っています。'], array['Nếu xử lý để không đặt giới hạn, tôi nghĩ sẽ không kịp lần release này.']),
  ('c8191c94-0072-5032-a685-3cd65c301b4e'::uuid, 0, 'dự kiến', '対応工数を見積もった結果、少なくとも10人日かかる見込みです。', 'Sau khi ước tính effort xử lý, dự kiến sẽ mất ít nhất 10 ngày công.', array['うーん…。そうですか。対応には、どの程度工数がかかる見込みですか。', 'メールでお知らせした通り、12月にWeb版への移行の受け入れテストを行う見込みです。'], array['Ừm… vậy sao. Dự kiến việc xử lý sẽ tốn khoảng bao nhiêu công sức?', 'Như đã thông báo qua email, dự kiến vào tháng 12 sẽ thực hiện kiểm thử nghiệm thu việc chuyển sang bản Web.']),
  ('d0cf570d-1e98-519d-a9c6-beb2a4bfc100'::uuid, 0, 'ít nhất', '対応工数を見積もった結果、少なくとも10人日かかる見込みです。', 'Sau khi ước tính effort xử lý, dự kiến sẽ mất ít nhất 10 ngày công.', '{}'::text[], '{}'::text[]),
  ('4dd602c7-328f-5fa3-af14-6313735a8a32'::uuid, 0, 'thông cảm, hiểu cho', '制限なしのバージョンの納品、予めご了承くださいませんか。', 'Về việc giao bản không giới hạn, quý công ty có thể thông cảm/chấp thuận trước không?', '{}'::text[], '{}'::text[]),
  ('e819e10a-e823-5453-97f0-de174b49553a'::uuid, 0, 'kiểm thử nghiệm thu', '受け入れテストの日程も近いので、一旦、担当者とも相談します。', 'Vì lịch kiểm thử nghiệm thu cũng đã gần, trước mắt tôi sẽ trao đổi với người phụ trách.', array['メールでお知らせした通り、12月にWeb版への移行の受け入れテストを行う見込みです。'], array['Như đã thông báo qua email, dự kiến vào tháng 12 sẽ thực hiện kiểm thử nghiệm thu việc chuyển sang bản Web.']),
  ('b0b4627a-487d-583b-b29c-77e8593ca9f7'::uuid, 0, 'lịch, lịch trình', '受け入れテストの日程も近いので、一旦、担当者とも相談します。', 'Vì lịch kiểm thử nghiệm thu cũng đã gần, trước mắt tôi sẽ trao đổi với người phụ trách.', '{}'::text[], '{}'::text[]),
  ('a56db5a6-0f4c-5828-9919-9dcd600c114e'::uuid, 0, 'tạm thời, trước mắt', '受け入れテストの日程も近いので、一旦、担当者とも相談します。', 'Vì lịch kiểm thử nghiệm thu cũng đã gần, trước mắt tôi sẽ trao đổi với người phụ trách.', array['その後、一旦、弊社で対応の優先順位を決めて、連絡します。'], array['Sau đó công ty chúng tôi sẽ tạm thời quyết định thứ tự ưu tiên rồi liên lạc.']),
  ('293d3aac-286f-50f6-98bc-e1a826844f55'::uuid, 0, 'trong ngày mai', 'はい、できれば、明日中にご回答いただけないでしょうか。', 'Vâng, nếu được, quý công ty có thể phản hồi trong ngày mai không ạ?', '{}'::text[], '{}'::text[]),
  ('b7c2322a-7aa4-5175-9ee3-deee57dd733d'::uuid, 0, 'ẩn đi, không hiển thị', '不要な項目は、非表示にすることもできます。', 'Cũng có thể ẩn các mục không cần thiết.', '{}'::text[], '{}'::text[]),
