  ('7e414f52-2696-5d2c-addb-f46850117a64'::uuid, 0, 'đặt deliverable vào thư mục', '最後に、納品物をフォルダに配置する予定です。', 'Cuối cùng, dự kiến đặt sản phẩm bàn giao vào thư mục.', '{}'::text[], '{}'::text[]),
  ('92eb1135-d8f8-5c75-be34-9e92a267a727'::uuid, 0, 'quy trình gỡ cài đặt', 'ご要望に応じて、アンインストールの手順についても記載しています。', 'Theo mong muốn của các bạn, chúng tôi đang mô tả cả các bước gỡ cài đặt.', array['ご要望に応じて、インストール手順書には、アンインストールの手順についても記載しています。', 'システムの動作確認に際して、インストールとアンインストールの手順を記載したドキュメントもレビューします。'], array['Theo yêu cầu của quý công ty, trong hướng dẫn cài đặt chúng tôi cũng ghi cả quy trình gỡ cài đặt.', 'Khi kiểm tra hoạt động của hệ thống, chúng tôi cũng sẽ review cả tài liệu mô tả quy trình cài đặt và gỡ cài đặt.']),
  ('6947650b-22bd-5f36-9da2-1e2a9856997f'::uuid, 0, 'vẫn còn các giới hạn', '今回の納品にはどのような制限事項が残っていますか。', 'Bàn giao lần này còn những giới hạn nào?', '{}'::text[], '{}'::text[]),
  ('981c6c5a-cdc6-53bb-b402-e90e0ad05877'::uuid, 0, 'tối đa 10 ảnh, mỗi ảnh 2MB', 'お気に入りに登録できる画像は最大２MBで10枚までです。', 'Hình ảnh có thể đăng ký trong phần Favorites tối đa là 10 tấm, dung lượng mỗi tấm không quá 2MB.', '{}'::text[], '{}'::text[]),
  ('7576d559-f1ee-5054-a70f-f40769cb7d2c'::uuid, 0, 'do cấu hình thiết bị', '見積りの際に説明した通り、端末のスペックによるものです。', 'Như đã giải thích khi báo giá, nguyên nhân là do cấu hình của thiết bị.', '{}'::text[], '{}'::text[]),
  ('b82add01-b6df-5fa3-95da-76b339923072'::uuid, 0, 'khuyến nghị RAM từ 4GB trở lên', '動作環境として、RAMは４GB以上を推奨します。', 'Về môi trường hoạt động, khuyến nghị RAM từ 4GB trở lên.', '{}'::text[], '{}'::text[]),
  ('d0f5e662-b811-5bbe-b20b-d48e964badc7'::uuid, 0, 'băng thông hiện tại khó đáp ứng', '現在の帯域幅では対応が難しいと思います。', 'Tôi nghĩ với băng thông hiện tại thì khó đáp ứng.', '{}'::text[], '{}'::text[]),
  ('ec4e045a-1db4-52e1-b591-63ef963e79dd'::uuid, 0, 'bổ sung đường truyền của nhà cung cấp khác', '他のプロバイダの回線を追加する必要があります。', 'Cần bổ sung đường truyền của nhà cung cấp khác.', '{}'::text[], '{}'::text[]),
  ('bb34c860-cbeb-5995-aa84-efb786228bf2'::uuid, 0, 'đến chỗ của ai đó', '分からないことがあれば、いつでも私の席に来てください。', 'Nếu có điều gì không hiểu, hãy đến chỗ tôi bất cứ lúc nào.', '{}'::text[], '{}'::text[]),
  ('5bf388d6-929c-5e60-adb8-fa36d1b32320'::uuid, 0, 'lỗi, bug', 'まず不具合管理システムに登録します。', 'Trước hết đăng ký vào hệ thống quản lý lỗi.', array['そこで、不具合が出た場合の体制について、念のためもう一度聞かせてください。', '定例会のときにも相談しましたが、受入テストで検出された不具合は、まず私が原因を分析することになっています。'], array['Vì vậy, cho tôi hỏi lại để chắc chắn về cơ chế khi có lỗi.', 'Như đã trao đổi trong họp định kỳ, với lỗi phát hiện trong UAT thì trước hết tôi sẽ phân tích nguyên nhân.']),
  ('9c5ab7c4-24ff-583f-83e1-3b5213c31968'::uuid, 0, 'phát hiện, tìm ra', '定例会のときにも相談しましたが、受入テストで検出された不具合は、まず私が原因を分析することになっています。', 'Như đã trao đổi trong họp định kỳ, với lỗi phát hiện trong UAT thì trước hết tôi sẽ phân tích nguyên nhân.', '{}'::text[], '{}'::text[]),
  ('048f0d25-b1b3-50b9-b4f5-9d184fcba5dd'::uuid, 0, 'thứ tự ưu tiên', '優先順位を決めて、連絡します。', 'Tôi sẽ quyết định thứ tự ưu tiên rồi liên lạc.', array['弊社で対応の優先順位を決めて、連絡します。', 'その後、お客様側で対応の優先順位を決めて連絡します。'], array['Công ty chúng tôi quyết định thứ tự ưu tiên xử lý rồi liên lạc.', 'Sau đó phía khách hàng quyết định thứ tự ưu tiên và liên lạc lại.']),
  ('c441395a-7e95-5fab-a0b0-1a4b343f4f35'::uuid, 0, 'sản phẩm, thành phẩm', '先日、成果物を受け取りました。', 'Hôm trước chúng tôi đã nhận sản phẩm bàn giao.', '{}'::text[], '{}'::text[]),
  ('bcb1815a-f28c-556e-8317-0207dd55a493'::uuid, 0, 'phân chia, phân loại', 'その後、どちらで対応するのか切り分けるのですね。', 'Sau đó sẽ phân chia bên nào xử lý, phải không?', array['まず原因を分析し、対応する担当を切り分け、再現手順も確認します。', '分析に加えて、私が対応するものとオフショアが対応するものの切り分けもします。'], array['Trước hết, phân tích nguyên nhân, phân chia người phụ trách xử lý và xác nhận cả bước tái hiện.', 'Ngoài phân tích, tôi cũng phân loại phần tôi xử lý và phần offshore xử lý.']),
  ('dff9a465-a385-50ce-8656-844a670f41b0'::uuid, 0, 'trình tự tái hiện', '再現手順についても確認します。', 'Tôi cũng xác nhận quy trình tái hiện.', array['まず原因を分析し、対応する担当を切り分け、再現手順も確認します。'], array['Trước hết, phân tích nguyên nhân, phân chia người phụ trách xử lý và xác nhận cả bước tái hiện.']),
  ('c0b3033a-94ae-5bef-9606-c974e6615baf'::uuid, 0, 'đi/đến để trao đổi', '困ったときは、相談に来てください。', 'Khi gặp khó khăn, hãy đến trao đổi.', '{}'::text[], '{}'::text[]),
