  ('563ae821-9018-5f5b-b635-85a6aba5948c'::uuid, 0, 'mật độ', '情報の密度が高くて、分かりにくいです。', 'Mật độ thông tin cao nên khó hiểu.', '{}'::text[], '{}'::text[]),
