  ('30169c46-89bd-5205-8e33-7ddc50e2c312'::uuid, 0, 'hằng tháng', '月次の報告会は、毎月初めに行います。', 'Buổi họp báo cáo hằng tháng được tổ chức vào đầu mỗi tháng.', '{}'::text[], '{}'::text[]),
  ('25b29bc0-45fd-52dc-80e7-adca159193f7'::uuid, 0, 'ngày giờ', '会議の日時を教えてください。', 'Xin cho biết ngày giờ cuộc họp.', '{}'::text[], '{}'::text[]),
  ('2b1bfd4f-18b0-541f-8d06-d2d8986834e1'::uuid, 0, 'ngày hôm kia (lịch sự)', '一昨日、資料を送りました。', 'Hôm kia tôi đã gửi tài liệu.', '{}'::text[], '{}'::text[]),
  ('661acd86-d0c4-59a2-9e2c-428e09b9250b'::uuid, 0, 'phase, giai đoạn', '次のフェーズに進みます。', 'Chúng ta chuyển sang phase tiếp theo.', '{}'::text[], '{}'::text[]),
  ('a48f8553-33df-53c2-aa21-6c2cb11d092d'::uuid, 0, 'pending, tạm ngưng', 'この件は、いったん保留にします。', 'Vụ việc này tạm thời để pending.', '{}'::text[], '{}'::text[]),
  ('b867ec7f-b961-5893-936f-0ccde0d9dfbe'::uuid, 0, 'giải pháp cải thiện', '改善策をチームで検討します。', 'Cả nhóm cùng xem xét giải pháp cải thiện.', '{}'::text[], '{}'::text[]),
  ('2d4684ae-c367-5a10-843b-b0f24da0ee07'::uuid, 0, 'phối hợp, liên kết', '他のチームと連携して進めます。', 'Chúng tôi phối hợp với các nhóm khác để tiến hành.', '{}'::text[], '{}'::text[]),
  ('40b08be3-28bd-5a12-b972-c0ed446be7ba'::uuid, 0, 'phân loại', '問い合わせの内容を分類します。', 'Tôi phân loại nội dung các yêu cầu hỏi đáp.', '{}'::text[], '{}'::text[]),
  ('79a2d73e-5b08-5858-9849-632b43f59862'::uuid, 0, 'đính kèm', '資料を添付して、メールを送ります。', 'Tôi đính kèm tài liệu và gửi email.', '{}'::text[], '{}'::text[]),
  ('e3f12729-e938-519f-8bf2-56bd7a000691'::uuid, 0, 'ngày cuối cùng', '本日はリーさんのオンサイト最終日です。', 'Hôm nay là ngày onsite cuối cùng của chị Lee.', array['受入テストサポートと展開も終わり、本日はオンサイトの最終日です。'], array['Hỗ trợ UAT và triển khai đã kết thúc; hôm nay là ngày onsite cuối cùng.']),
  ('372cb456-b056-5610-b4b6-7529377aaf8c'::uuid, 0, 'trao đổi, thảo luận', 'そして、今後の計画についても話し合います。', 'Sau đó hai bên cũng trao đổi về kế hoạch sắp tới.', '{}'::text[], '{}'::text[]),
  ('d411fbf0-ccaf-5dae-8412-a0db5706447f'::uuid, 0, 'họp tổng kết dự án, retrospective', '来週は振り返り会議をすることになっていますが、そこでも良かった点として報告させてもらいます。', 'Tuần sau sẽ có họp tổng kết; chúng tôi cũng sẽ báo cáo đây là một điểm tích cực.', '{}'::text[], '{}'::text[]),
  ('b9065175-7ce1-5683-8275-2c1cc2b138b8'::uuid, 0, 'quyết định, chốt', 'まだ確定していませんが、次はもう少し規模の大きなプロジェクトを実施する予定です。', 'Tuy chưa chắc chắn nhưng tiếp theo dự kiến sẽ thực hiện dự án có quy mô lớn hơn một chút.', array['確定すれば、クラウドの人材など要員追加を依頼することになると思います。', 'まだ確定していませんが、次はもう少し規模の大きなプロジェクトを実施する予定です。'], array['Khi được chốt, tôi nghĩ chúng tôi sẽ cần yêu cầu bổ sung nhân sự, như nhân lực cloud.', 'Tuy chưa chắc chắn nhưng tiếp theo dự kiến sẽ thực hiện dự án có quy mô lớn hơn một chút.']),
  ('eb9dc064-0c2d-5c94-8be7-62a1419b8f26'::uuid, 0, 'dừng tay, tạm ngừng', '作業の手を止めてこちらへ集まってください。', 'Hãy dừng tay và tập trung lại đây.', '{}'::text[], '{}'::text[]),
  ('a529e99b-2f9f-5b90-bb4c-aff91aacbeea'::uuid, 0, 'tập hợp', '明日の9時に、会社の前に集合してください。', 'Xin hãy tập trung trước công ty lúc 9 giờ sáng mai.', '{}'::text[], '{}'::text[]),
  ('711b25d8-fef4-58dd-9647-0fa26d6c7d4c'::uuid, 0, 'đón, có được', 'おかげさまで、本日を迎えることができました。', 'Nhờ mọi người, chúng ta đã có được ngày hôm nay.', array['オンサイトの皆さんに支えられ、おかげさまで本日を迎えることができました。', 'おかげさまで、受入テストの間、大きな不具合もなく、本日を迎えることができました。'], array['Nhờ sự hỗ trợ của mọi người onsite, chúng ta đã có thể đến được ngày hôm nay.', 'Nhờ mọi người, trong UAT không có lỗi lớn và chúng ta đã có ngày hôm nay.']),
  ('f2f63935-8616-526c-9c66-f87fd29377a3'::uuid, 0, 'suôn sẻ', 'リーさんがいてくれたので、技術面で課題が出てきたときもスムーズに会話ができ、対応も早かったですね。', 'Vì có chị Lee nên ngay cả khi phát sinh vấn đề kỹ thuật, việc trao đổi cũng thuận lợi và xử lý nhanh.', '{}'::text[], '{}'::text[]),
  ('97c276c2-bbf9-55cc-b3b6-5fef38225a4a'::uuid, 0, 'quy mô', 'まだ確定していませんが、次はもう少し規模の大きなプロジェクトを実施する予定です。', 'Tuy chưa chắc chắn nhưng tiếp theo dự kiến sẽ thực hiện dự án có quy mô lớn hơn một chút.', '{}'::text[], '{}'::text[]),
  ('826499f5-d05a-596a-b659-ffdd34a32d87'::uuid, 0, 'cloud', 'クラウドの人材など、要員追加が必要になると思います。', 'Có thể sẽ cần bổ sung nhân lực, ví dụ nhân sự cloud.', array['確定すれば、クラウドの人材など要員追加を依頼することになると思います。'], array['Khi được chốt, tôi nghĩ chúng tôi sẽ cần yêu cầu bổ sung nhân sự, như nhân lực cloud.']),
  ('2d75e26b-7ab7-5062-ab2e-5b411e8ace7f'::uuid, 0, 'nhân tài, nguồn nhân lực', 'クラウドの人材など、要員追加が必要になると思います。', 'Có thể sẽ cần bổ sung nhân lực, ví dụ nhân sự cloud.', array['確定すれば、クラウドの人材など要員追加を依頼することになると思います。'], array['Khi được chốt, tôi nghĩ chúng tôi sẽ cần yêu cầu bổ sung nhân sự, như nhân lực cloud.']),
  ('8ecbd09f-5ae2-5372-94df-1a91fece08a2'::uuid, 0, 'nhân sự cần cho công việc', 'クラウドの人材など、要員追加が必要になると思います。', 'Có thể sẽ cần bổ sung nhân lực, ví dụ nhân sự cloud.', array['確定すれば、クラウドの人材など要員追加を依頼することになると思います。'], array['Khi được chốt, tôi nghĩ chúng tôi sẽ cần yêu cầu bổ sung nhân sự, như nhân lực cloud.']),
  ('4196d7a4-44d6-57a6-aa7b-9a570f3c6c17'::uuid, 0, 'sprint', '今回のスプリントは2週間です。', 'Sprint lần này kéo dài 2 tuần.', '{}'::text[], '{}'::text[]),
  ('15fa9e2e-7b26-57bb-8181-66882836d36b'::uuid, 0, 'hỗ trợ', 'オンサイトの皆さんに支えられ、おかげさまで本日を迎えることができました。', 'Nhờ sự hỗ trợ của mọi người onsite, chúng ta đã có thể đến được ngày hôm nay.', '{}'::text[], '{}'::text[]),
  ('f215dae0-8e82-5b3a-bca2-f077d6485b60'::uuid, 0, 'thành lập', '会社は2010年に創立されました。', 'Công ty được thành lập năm 2010.', '{}'::text[], '{}'::text[]),
  ('c259b092-fa97-57d1-8aea-380cd20182fe'::uuid, 0, 'kỷ niệm một năm', '今日はプロジェクト１周年記念です。', 'Hôm nay là kỷ niệm một năm của dự án.', '{}'::text[], '{}'::text[]),
  ('112ea768-51f7-563b-a9e2-538530839d56'::uuid, 0, 'buổi retro, retrospective meeting', 'スプリントの最後にレトロを行います。', 'Cuối sprint chúng tôi tổ chức buổi retro.', '{}'::text[], '{}'::text[]),
  ('1fc93eaa-d3b0-53ce-aee5-932dc28cc275'::uuid, 0, 'nâng phiên bản', '来月、システムをバージョンアップします。', 'Tháng sau chúng tôi nâng phiên bản hệ thống.', '{}'::text[], '{}'::text[]),
  ('4506bfa5-e2a5-50be-abaf-1299a7d072c9'::uuid, 0, 'hoãn', 'リリースを一週間延期します。', 'Chúng tôi hoãn release một tuần.', '{}'::text[], '{}'::text[]),
  ('57ed2908-04d2-58ff-bdb4-b38463b3d2da'::uuid, 0, 'kéo dài', '納期を三日間延長してもらえませんか。', 'Anh/chị có thể gia hạn hạn giao thêm ba ngày không?', '{}'::text[], '{}'::text[]),
  ('a67be993-f926-55f0-9bed-3bdb71609190'::uuid, 0, 'bắt đầu triển khai', '来週から、開発に着手します。', 'Từ tuần sau chúng tôi bắt đầu triển khai phát triển.', '{}'::text[], '{}'::text[]),
  ('204de31a-4306-5501-8c7c-6f049b5fcf14'::uuid, 0, 'độ ưu tiên', 'タスクの優先度を決めましょう。', 'Hãy quyết định độ ưu tiên của các tác vụ.', '{}'::text[], '{}'::text[]),
  ('3e332ff5-87fa-567a-86d1-2d445060c5a9'::uuid, 0, 'chuẩn hóa quy trình', 'プロセスの標準化を進めています。', 'Chúng tôi đang thúc đẩy chuẩn hóa quy trình.', '{}'::text[], '{}'::text[]),
  ('7d33ed76-4cdc-5c09-9f2d-d0d01eb49069'::uuid, 0, 'nhận đặt hàng', '新しいプロジェクトを受注しました。', 'Chúng tôi đã nhận được dự án mới.', '{}'::text[], '{}'::text[]),
  ('a9da805e-76aa-5929-9b0a-fdaee6a45d6e'::uuid, 0, 'giúp đỡ, trợ giúp', '皆様のお力添えに感謝します。', 'Tôi cảm ơn sự giúp đỡ của mọi người.', '{}'::text[], '{}'::text[]),
  ('07b4ddc1-6362-5982-a418-be77fc2ae187'::uuid, 0, 'chân thành, thực sự', '誠にありがとうございました。', 'Thực sự xin cảm ơn ạ.', '{}'::text[], '{}'::text[])
insert into grammar_points (id, title, explanation, example_jp, example_vi, level_id)
values
  ('71c9ba09-741f-572f-bdfe-4f9c5c84456b'::uuid, 'この度は、ご来社くださり、まことにありがとうございます。日本企業向けシステム開発部門を管理しております、ホアンと申します。どうぞよろしくお願いいたします。', 'Cảm ơn và giới thiệu bản thân', 'この度は、ご来社くださり、まことにありがとうございます。日本企業向けシステム開発部門を管理しております、ホアンと申します。どうぞよろしくお願いいたします。', 'Cảm ơn quý vị đã đến công ty chúng tôi lần này. Tôi là Hoan, phụ trách bộ phận phát triển hệ thống cho doanh nghiệp Nhật. Rất mong được hợp tác.', (select id from jlpt_levels where code = 'IT')),
  ('f5e17d61-5e68-5628-987b-197a0af4b337'::uuid, '私は、SESのIT部門でIT関連のプロジェクトを管理しています、小巻と申します。どうぞよろしくお願いいたします。', 'Giới thiệu trách nhiệm phía SES', '私は、SESのIT部門でIT関連のプロジェクトを管理しています、小巻と申します。どうぞよろしくお願いいたします。', 'Tôi là Komaki, hiện quản lý các dự án liên quan đến IT tại bộ phận IT của SES. Rất mong được hợp tác.', (select id from jlpt_levels where code = 'IT')),
  ('947f755a-cc48-5b92-8abb-ea3456ff5f67'::uuid, '私は日本のお客様向けのシステム開発プロジェクトを主に担当しております。今回のプロジェクトのPMをつとめることになりました、アンと申します。どうぞよろしくお願いいたします。', 'Giới thiệu công việc và vai trò PM', '私は日本のお客様向けのシステム開発プロジェクトを主に担当しております。今回のプロジェクトのPMをつとめることになりました、アンと申します。どうぞよろしくお願いいたします。', 'Tôi chủ yếu phụ trách các dự án phát triển hệ thống cho khách hàng Nhật. Tôi là An, được phân công làm PM của dự án lần này. Rất mong được hợp tác.', (select id from jlpt_levels where code = 'IT')),
  ('298a4c61-55cc-5d83-9bc9-dc765608a7f4'::uuid, '今回は、皆さんとベトナムでプロジェクトのキックオフをするために参りましたので、2日間どうぞよろしくお願いします。', 'Nêu mục đích chuyến công tác', '今回は、皆さんとベトナムでプロジェクトのキックオフをするために参りましたので、2日間どうぞよろしくお願いします。', 'Lần này tôi đến Việt Nam để kickoff dự án cùng mọi người; trong hai ngày tới mong mọi người hỗ trợ.', (select id from jlpt_levels where code = 'IT')),
  ('c53aca2a-f9d4-5c59-89ef-4bdb6d221484'::uuid, 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'Nói về vinh dự và người hỗ trợ sau khi về nước', 'はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。', 'Vâng, phía chúng tôi cũng rất vinh dự vì có thể kickoff trực tiếp. Sau khi quý vị về nước, Lee của SES sẽ làm onsite từ công đoạn xác định yêu cầu. Khi đó cũng mong được hợp tác.', (select id from jlpt_levels where code = 'IT')),
  ('7963e74f-ebf3-5a48-bac8-3e66608a90fa'::uuid, 'A向けのB', 'B dành cho/nhắm tới A: 日本のお客様向けのシステム.', '日本のお客様向けのシステム', null, (select id from jlpt_levels where code = 'IT')),
  ('d31c8d92-81ba-504d-a7ed-3d79f24b95f4'::uuid, '〜を担当しております', 'Cách nói khiêm nhường, trang trọng: đang phụ trách ~.', null, null, (select id from jlpt_levels where code = 'IT')),
  ('3960044b-ac5d-5dc2-bbbf-20f6a97d5906'::uuid, '〜をつとめることになりました', 'Được quyết định/phân công đảm nhận vai trò ~.', null, null, (select id from jlpt_levels where code = 'IT')),
  ('4379a954-1839-5345-badd-a869c9422fd7'::uuid, 'V-るために参りました', 'Đến để làm ~; 参りました là khiêm nhường của 来ました.', null, null, (select id from jlpt_levels where code = 'IT')),
  ('f844f080-0f76-5904-8c7b-a91ce0fabb6d'::uuid, '〜ができて、光栄です', 'Rất vinh dự vì có thể ~.', null, null, (select id from jlpt_levels where code = 'IT')),
  ('38cb8195-d663-5433-b44a-9a85384d5c87'::uuid, '〜することになっております', 'Đã được sắp xếp/quyết định sẽ ~; thường dùng thông báo kế hoạch chính thức.', null, null, (select id from jlpt_levels where code = 'IT')),
  ('1c1f0ea9-5047-5562-8fbb-5509b84944df'::uuid, 'では、プロジェクトのキックオフミーティングを始めたいと思います。', 'Mở đầu cuộc họp lịch sự.', 'では、プロジェクトのキックオフミーティングを始めたいと思います。', null, (select id from jlpt_levels where code = 'IT')),
  ('170e29e6-1599-54a3-98b7-ff90598450f6'::uuid, 'まず、本日のアジェンダについて説明いたします。', 'Bắt đầu giải thích nội dung/agenda.', 'まず、本日のアジェンダについて説明いたします。', null, (select id from jlpt_levels where code = 'IT')),
  ('22e02e86-f2a5-5f3e-8c40-413abf6b1222'::uuid, 'この順番で進めたいと思いますが、よろしいでしょうか。', 'Đề nghị xác nhận thứ tự tiến hành.', 'この順番で進めたいと思いますが、よろしいでしょうか。', null, (select id from jlpt_levels where code = 'IT')),
  ('f6446068-09d7-5489-b10c-b04e0658cbee'::uuid, 'ご説明ありがとうございます。', 'Cảm ơn người vừa giải thích.', 'ご説明ありがとうございます。', null, (select id from jlpt_levels where code = 'IT')),
  ('d6eb4045-9b37-5db1-842d-c4c8c8f441fe'::uuid, '既存システムをベースに、WebGLを取り入れて機能追加と変更をします。', 'Trình bày giải pháp phát triển dựa trên hệ thống có sẵn.', '既存システムをベースに、WebGLを取り入れて機能追加と変更をします。', null, (select id from jlpt_levels where code = 'IT')),
  ('e4835123-3ed1-5b05-873e-c80989844642'::uuid, 'ロジックに合わせて直したほうがよいものがありましたら、教えていただければと思います。', 'Lịch sự nhờ thông báo nếu có điểm nên chỉnh sửa.', 'ロジックに合わせて直したほうがよいものがありましたら、教えていただければと思います。', null, (select id from jlpt_levels where code = 'IT')),
  ('15256d11-9200-5abd-8fbb-3bd9b296c4be'::uuid, '少しは要件の変更が発生するかもしれませんが、ほぼ決まっていますので、それで問題ないと思います。', 'Nêu khả năng thay đổi nhưng đánh giá phương án vẫn ổn.', '少しは要件の変更が発生するかもしれませんが、ほぼ決まっていますので、それで問題ないと思います。', null, (select id from jlpt_levels where code = 'IT')),
  ('a88ec0f7-f8c7-572d-89a4-ada92de26a1c'::uuid, 'UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。', 'Đề xuất hành động vì một mục tiêu cụ thể.', 'UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。', null, (select id from jlpt_levels where code = 'IT')),
  ('116098d8-8416-5284-a620-b58043bcb700'::uuid, 'そうすれば、手戻りを減らせると考えています。', 'Nêu kết quả mong đợi của đề xuất.', 'そうすれば、手戻りを減らせると考えています。', null, (select id from jlpt_levels where code = 'IT')),
  ('2227d63a-0d7a-5e6b-9d75-3d951524252e'::uuid, '実は、SRSで一部決まっていない内容があります。', 'Mở đầu để nói thật/đề cập thông tin quan trọng còn tồn đọng.', '実は、SRSで一部決まっていない内容があります。', null, (select id from jlpt_levels where code = 'IT')),
  ('d891dd6b-8f86-5d51-a07d-6b4c6fb81cd6'::uuid, 'ここまでプロジェクト概要と開発手法について説明しましたが、何かご質問はありますか。', 'Kết phần giải thích và mời câu hỏi.', 'ここまでプロジェクト概要と開発手法について説明しましたが、何かご質問はありますか。', null, (select id from jlpt_levels where code = 'IT')),
