  ('ced3dba9-1560-5217-ba36-fb00d9fa6097'::uuid, '課題などは私が小巻様と確認すればよいという理解ですが、間違いないでしょうか。', 'Xác nhận lại hiểu biết về trách nhiệm/đầu mối.', '課題などは私が小巻様と確認すればよいという理解ですが、間違いないでしょうか。', null, (select id from jlpt_levels where code = 'IT')),
  ('16da0cfe-e167-5c07-9e64-cb72194c97cb'::uuid, '私がそれらの情報をまとめて、小巻様に報告します。', 'Mô tả hành động tổng hợp và báo cáo.', '私がそれらの情報をまとめて、小巻様に報告します。', null, (select id from jlpt_levels where code = 'IT')),
  ('9384dbdf-816b-5fbd-b69b-d45fb5867445'::uuid, '場合によっては、リンも参加いたします。', 'Nêu khả năng một người sẽ tham gia tùy tình huống.', '場合によっては、リンも参加いたします。', null, (select id from jlpt_levels where code = 'IT')),
  ('5382fd5d-d6d8-5372-9308-2b063f990e29'::uuid, '紹介します。プロジェクト実施のためにベトナムから来てくださったDKH社のリーさんです。', 'Giới thiệu người tới để thực hiện dự án.', '紹介します。プロジェクト実施のためにベトナムから来てくださったDKH社のリーさんです。', null, (select id from jlpt_levels where code = 'IT')),
