  ('d66216ed-ad8a-52f7-ba84-05a05da759b3'::uuid, '日本は初めてですので、わからないことも多いかと思いますが、どうぞよろしくお願いいたします。', 'Nói về việc lần đầu đến nơi mới và xin hỗ trợ lịch sự.', '日本は初めてですので、わからないことも多いかと思いますが、どうぞよろしくお願いいたします。', null, (select id from jlpt_levels where code = 'IT')),
