  ('b0c526a6-6022-5e77-8a24-54db5f219c7f'::uuid, '後で予約サイトのリンクを送っておきますね。', 'Lát nữa tôi sẽ gửi sẵn link trang đặt phòng nhé.', '後で予約サイトのリンクを送っておきますね。', 'Lát nữa tôi sẽ gửi sẵn link trang đặt phòng nhé.', (select id from jlpt_levels where code = 'IT')),
