  ('2e2288ce-6b8a-54fc-917b-c9d85824cdfe'::uuid, '席を離れるときは、机の上に社外秘の資料などを置いたままにしないようにしてください。', 'Khi rời chỗ, đừng để nguyên tài liệu mật trên bàn.', '席を離れるときは、机の上に社外秘の資料などを置いたままにしないようにしてください。', 'Khi rời chỗ, đừng để nguyên tài liệu mật trên bàn.', (select id from jlpt_levels where code = 'IT')),
