  ('fc24abbe-034d-58c9-94d8-d18c437f9cd1'::uuid, 'IT部門のセキュリティチェックを受けてからでないと、社内で使ってはいけないことになっています。', 'Nếu chưa được bộ phận IT kiểm tra bảo mật thì không được dùng trong công ty.', 'IT部門のセキュリティチェックを受けてからでないと、社内で使ってはいけないことになっています。', 'Nếu chưa được bộ phận IT kiểm tra bảo mật thì không được dùng trong công ty.', (select id from jlpt_levels where code = 'IT')),
  ('05a4d373-9263-5fda-9168-950ec325709e'::uuid, 'プロジェクトのメンバーが全員そろいましたので、要件の説明会を始めたいと思います。', 'Vì toàn bộ thành viên dự án đã có mặt, tôi muốn bắt đầu buổi giải thích yêu cầu.', 'プロジェクトのメンバーが全員そろいましたので、要件の説明会を始めたいと思います。', 'Vì toàn bộ thành viên dự án đã có mặt, tôi muốn bắt đầu buổi giải thích yêu cầu.', (select id from jlpt_levels where code = 'IT')),
