  ('54a8aa39-627e-5b49-ad0b-dce747be10ad'::uuid, '皆さんにとってはなじみのあるものだと思います。', 'Tôi nghĩ đó là thứ quen thuộc với mọi người.', '皆さんにとってはなじみのあるものだと思います。', 'Tôi nghĩ đó là thứ quen thuộc với mọi người.', (select id from jlpt_levels where code = 'IT')),
