  ('f77bc150-9323-5c08-b2c4-239d32221848'::uuid, 'ご要望に応じて、〜しています。', 'Xác nhận đã thực hiện theo yêu cầu.', 'ご要望に応じて、〜しています。', null, (select id from jlpt_levels where code = 'IT')),
  ('67b1a7da-7470-5a78-b42c-5caf66d2b84a'::uuid, '〜ので、後ほど〜させてください。', 'Xin phép thực hiện/xác nhận lại sau khi có lý do.', '〜ので、後ほど〜させてください。', null, (select id from jlpt_levels where code = 'IT')),
  ('e3212b32-895b-5b68-9eb1-0d93e8fd078f'::uuid, '〜できる画像は最大〜までです。', 'Mô tả giới hạn bằng thể khả năng và định lượng.', '〜できる画像は最大〜までです。', null, (select id from jlpt_levels where code = 'IT')),
  ('48d0a988-27e8-501c-a7cf-d5ad03e51038'::uuid, '〜によるものです。', 'Giải thích nguyên nhân.', '〜によるものです。', null, (select id from jlpt_levels where code = 'IT')),
  ('d95ba65f-b2ce-5516-83b7-291de5526513'::uuid, '弊社でも承知しています。', 'Xác nhận công ty mình đã nắm rõ một thông tin.', '弊社でも承知しています。', null, (select id from jlpt_levels where code = 'IT')),
  ('a535fd92-ef78-57ed-8d74-e636a7732a96'::uuid, 'A に加えて、B もします', 'Ngoài phân tích, tôi cũng phân loại/chia phần việc.', '分析に加えて、…の切り分けもします。', 'Ngoài phân tích, tôi cũng phân loại/chia phần việc.', (select id from jlpt_levels where code = 'IT')),
  ('49e4ab4d-f9b0-5ff6-bca8-03aafc77a48d'::uuid, 'A に際して、B', '〜に際して trang trọng hơn 〜するとき; phù hợp trong công việc, tài liệu và cuộc họp.', '確認に際して分からないことがあったら、…', 'Nếu có điều không rõ khi xác nhận thì…', (select id from jlpt_levels where code = 'IT')),
  ('dec4281c-66f0-5cf9-b7e3-4b7e74397f72'::uuid, '優先順位を決めて、連絡します', 'Quyết định thứ tự ưu tiên rồi liên lạc. Cụm này giúp nói rõ trình tự trách nhiệm giữa các bên.', null, null, (select id from jlpt_levels where code = 'IT')),
  ('c0818c29-1117-5b2b-9669-8942e0e374ef'::uuid, 'これまで〜お疲れさまでした', 'Cảm ơn chị Lee đã vất vả trong khoảng bốn tháng qua.', 'リーさん、これまで約４か月間お疲れさまでした。', 'Cảm ơn chị Lee đã vất vả trong khoảng bốn tháng qua.', (select id from jlpt_levels where code = 'IT')),
  ('173bb9a1-02e2-5b79-838d-5b384ad35ffb'::uuid, '〜を迎えることができました', 'Nhờ mọi người, chúng ta đã có được ngày hôm nay.', 'おかげさまで、本日を迎えることができました。', 'Nhờ mọi người, chúng ta đã có được ngày hôm nay.', (select id from jlpt_levels where code = 'IT')),
  ('ece2e753-b143-535e-af95-92d512795865'::uuid, '〜に向けて、〜ましょう', 'Hãy cùng xem xét các điểm cần rà soát cho các dự án sắp tới.', '今後のプロジェクトに向けて見直すべきところについても検討しましょう。', 'Hãy cùng xem xét các điểm cần rà soát cho các dự án sắp tới.', (select id from jlpt_levels where code = 'IT')),
  ('53de05b8-f75c-509e-a3d8-e6937688b123'::uuid, 'まだ確定していませんが、〜', 'Dùng để nêu dự định/tình hình chưa được chốt, tránh khẳng định quá sớm.', null, null, (select id from jlpt_levels where code = 'IT'))
